import Foundation

/// The Greenlandic passages.
///
/// Written rather than translated: about sixty of the English passages
/// are etymologies of English words and are simply false in any other
/// language, so this bank comes from its own word histories, its own
/// literature and its own proverbs.
extension Quotes {
    static let greenlandic: [Passage] = [
        // MARK: - Beginnings
        Passage(text: "Kalaallisut -ssaq: suli pinngitsoq. Nerisassaq tassaavoq nerineqassasoq, illussaq tassaavoq illunngortussaq. Oqaatsit taamaattut suli pisimanngitsunut atorneqartarput.", source: "Kalaallisut", theme: .beginnings, subtheme: .theFirstAct),
        Passage(text: "Tingivoq: timmisartoq qummut aallarpoq. Tingeruttorpoq: nunamiinnerup naggataa, suli nunami, kisianni aatsaat qummut nuulluni. Oqaaseq ataaseq piffissamut ataatsimut.", source: "Kalaallisut", theme: .beginnings, subtheme: .theFirstAct),
        Passage(text: "Naatsiaq ammarpat naasunngorpoq, uteqqinnerlu ajorpoq. Naasup inuunerani pisoq taanna ataasiinnarmik pisarpoq, kingumullu aqqusaarneqarsinnaanani.", source: "Naasut", theme: .beginnings, subtheme: .theFirstAct),
        Passage(text: "Timmiaaraq mannermik kigutaaraminik ammartarpoq. Anisereerpat ullut arlallit qaangiummata kigutaaraq peertarpoq, atorneqarnikuulluni ataasiinnarmik.", source: "Timmissat", theme: .beginnings, subtheme: .theFirstAct),
        Passage(text: "Sikunippoq: imaq sikoqalerpoq. Ukiup ilaani ulloq ataaseq imaq qaqortumik matuneqartarpoq, ullullu tulliani angalanermut aqqutaanngorluni.", source: "Siku", theme: .beginnings, subtheme: .theFirstAct),
        Passage(text: "Kalaallisut -qqaaq: siulliulluni. Oqaqqaarpoq tassaavoq siullermik oqartoq, oqaasertarlu taanna paasititsivoq allat kingorna oqarumaartut.", source: "Kalaallisut", theme: .beginnings, subtheme: .theFirstAct),
        Passage(text: "Iluliaq sermermit qimanneqarpat aatsaat iluliunngorpoq. Taamaanngikkallarluni sermersuup ilagaa, ukiuni amerlasuuni nuunnermik utaqqisimalluni.", source: "Siku", theme: .beginnings, subtheme: .theFirstAct),
        Passage(text: "Kalaallit oqaluttuaat siulliit Nuummi naqinneqarput 1859-mi. Aron Kangermioq assiliartaminik ilanngussivoq, kalaallillu atuakkiortut aallartipput.", source: "Aron Kangermioq (1822-1869)", theme: .beginnings, subtheme: .theFirstAct),
        Passage(text: "Puisip piaraa sikup qaavani inunngortarpoq. Ullut arlallit qaangiuppata aatsaat imaanut aallartarpoq, taamaalilluni inuunini marlunnik aallartissimalluni.", source: "Uumasut", theme: .beginnings, subtheme: .theFirstAct),
        Passage(text: "Kalaallisut oqaasertaq -ler- aallartinnermik isumaqarpoq. Sulivoq aamma sulilerpoq assigiinngillat: siulleq suliaqarpoq, aappaa aatsaat suliami tungaanut saappoq.", source: "Kalaallisut", theme: .beginnings, subtheme: .theFirstAct),
        Passage(text: "Upernaakkut kuup sikua aatsaat aserorpoq. Ulloq taanna ukiuunerata isua, imermillu ingerlaannartup nipaa nunami tusaanerpaanngorluni.", source: "Nuna", theme: .beginnings, subtheme: .theFirstAct),
        Passage(text: "Meeraq oqaasertaminik siullermik oqarpat ilaquttai puiussanngilaat. Oqaaseq siulleq puiorneqartarpoq, ulloq puiorneqanngilaq.", source: "Ilaqutariit", theme: .beginnings, subtheme: .theFirstAct),
        Passage(text: "Naatsiaq mikisoq orpimmik annertuumik naasunngorsinnaavoq. Kalaallit Nunaanni orpiit mikisut ukiuni untritilinni angisuunngortarput, aputip ataani utaqqiinnarlutik.", source: "Naasut", theme: .beginnings, subtheme: .smallToLarge),
        Passage(text: "Kalaallisut -rujussuaq annertusaanermut atorneqarpoq, ilaannikkullu uteqqittarluni: qimmeq, qimmersuaq, qimmerujussuaq, qimmerujorujussuaq. Oqaaseq annertusiartortuarpoq.", source: "Kalaallisut", theme: .beginnings, subtheme: .smallToLarge),
        Passage(text: "Sermersuaq aputimik ataatsimik aallartissimavoq. Ukiut tusintit qaangiummata aput qaqorsuanngorpoq, Kalaallit Nunaatalu affaanit annerusortaa ullumikkut matulluni.", source: "Siku", theme: .beginnings, subtheme: .smallToLarge),
        Passage(text: "Nunaqarfik illumit ataatsimit aallartittarpoq. Illup eqqaani illut allat sananeqartarput, kingornagullu tamakkua ataatsimut ateqalersarlutik.", source: "Kalaallit Nunaat", theme: .beginnings, subtheme: .smallToLarge),
        Passage(text: "Nunami issittumi naasut mikisut kisimik naasinnaapput. Naasoq ataaseq mikisoq ukiorpassuarni annertusartoq inuup inuunerinit sivisunerusumik inuusarpoq.", source: "Naasut", theme: .beginnings, subtheme: .smallToLarge),
        Passage(text: "Kalaallisut oqaaseq ataaseq oqaasertanik arfinilinnik peqarsinnaavoq. Taamaalilluni oqaluttuaq tamarmi oqaatsimut ataatsimut inissinneqarsinnaavoq, allanik pisariaqartitsinani.", source: "Oqaatsit", theme: .beginnings, subtheme: .smallToLarge),
        Passage(text: "Immap ataani iluliup ilarujussua toqqorsimasarpoq. Qulaani takusaq annikitsuinnaavoq, annerpaartaalu immap ataaniinnarluni.", source: "Siku", theme: .beginnings, subtheme: .smallToLarge),
        Passage(text: "Ammassak mikisorujussuuvoq, katillugilli imarmiut inuunerinut tunngavipput. Puisit, arfeqqat timmissallu tamarmik taakkuninnga nerisaqarput.", source: "Imaq", theme: .beginnings, subtheme: .smallToLarge),
        Passage(text: "Kalaallisut -nnguaq mikisumik oqaaseqartarpoq, aammali asanninnermik. Illunnguaq illu mikisuuvoq, meeqqannguarli asasaq, angisuugaluarluniluunniit.", source: "Kalaallisut", theme: .beginnings, subtheme: .smallToLarge),
        Passage(text: "Ujarak mikisoq Ivittuummiit nunarsuaq tamaat angalavoq. Kryolit taanna aluminiumimut atorneqarpoq, timmisartullu nunarsuarmiut taassumannga sananeqarput.", source: "Nuna", theme: .beginnings, subtheme: .smallToLarge),
        Passage(text: "Qanik ataaseq qaammatit sisamat qaangiummata serminngortarpoq. Aput qulaani nallertoq ataaninngasunik oqimaassuseqartitsivoq, taakkualu sermersuanngorlutik.", source: "Sila", theme: .beginnings, subtheme: .smallToLarge),
        Passage(text: "Qimmeq ataaseq qamutinut naammanngilaq. Qimmit qulingiluat ataatsimoorlutik usilimmik qamutinik ulloq naallugu ingerlatsisinnaapput, ataasiakkaalli sapilluinnarlutik.", source: "Piniarneq", theme: .beginnings, subtheme: .smallToLarge),
        Passage(text: "Tuttut ataasiakkaat ukiakkut katersuuttarput. Katersuunneq amerlassusilerlugu tusintilinngortarpoq, aallartinnerali tuttut arlaqanngitsut aqqutaannik malinnaanerinnaavoq.", source: "Uumasut", theme: .beginnings, subtheme: .smallToLarge),
        Passage(text: "Kalaallisut oqaatsit iluanni oqaasertat tulleriissaarnerat aalajangersimavoq. Allanngortinneqarpat oqaaseq allamik isumaqalersarpoq, imaluunniit isumaqarunnaarluni.", source: "Kalaallisut", theme: .beginnings, subtheme: .whatAStartSettles),
        Passage(text: "Kalaallisut allanneqarnera 1973-mi nutarterneqarpoq, oqaluttarnermullu qanillineqarluni. Naqinnerit taakkua ullumikkut atuartitsinermi atorneqartut.", source: "Kalaallisut", theme: .beginnings, subtheme: .whatAStartSettles),
        Passage(text: "Paul Egede 1750-mi oqaatsinik nassuiaasumik atuakkiorpoq, ukiullu qulit qaangiummata oqaatsit ilusaannik allaaserisamik. Kalaallisut taamaalilluni allakkatigut aallartipput.", source: "Kalaallisut", theme: .beginnings, subtheme: .whatAStartSettles),
        Passage(text: "Samuel Kleinschmidt 1851-mi naqinnernik aaqqissuussivoq oqaatsit ilusaannut tunngasunik. Ukiut untritit qaangiummata oqaluttarneq allanngorpoq, allanneqarnerali uninngavoq.", source: "Kalaallisut", theme: .beginnings, subtheme: .whatAStartSettles),
        Passage(text: "2009-mi kalaallisut Kalaallit Nunaanni oqaatsitut aalajangersimasutut kisimiillutik inissinneqarput. Nunap oqaasii taamaalilluni allamit ilinniagaanngillat.", source: "Kalaallit Nunaat", theme: .beginnings, subtheme: .whatAStartSettles),
        Passage(text: "Kalaallisut oqaaseq tunngavimmik aallartittarpoq. Tunngaviup kingorna oqaasertat qassiinnaat inissinneqarsinnaapput, kisianni tunngavik namminerisaminik isumamik tigumiaavoq.", source: "Oqaatsit", theme: .beginnings, subtheme: .whatAStartSettles),
        Passage(text: "Kalaallisut nipit marluinnaat naapittarput. Nipit pingasut ataatsimut atanngillat, malittarisassarlu taanna oqaatsini takisuni tamani atuuppoq.", source: "Kalaallisut", theme: .beginnings, subtheme: .whatAStartSettles),
        Passage(text: "Naatsiaq nunami masannermik seqinermillu peqartumi naasunngortarpoq. Nunap ilusaa naasup ilusaanut siunnerfiliisarpoq, naasorlu allamut nuutsinneqarsinnaanani.", source: "Naasut", theme: .beginnings, subtheme: .whatAStartSettles),
        Passage(text: "Qajaq inuup timaanut naleqqussarneqartarpoq. Sanaartortoq imminut uuttortarpoq, qajarlu taamaalilluni inuup ataatsip qajaanngortarluni allanut naleqqutinnagu.", source: "Piniarneq", theme: .beginnings, subtheme: .whatAStartSettles),
        Passage(text: "Kalaallisut siuliusartut marluinnaapput, oqaatsillu sinneri tamarmik kingorna ilanngunneqartarlutik. Aallaqqaataani tunngavik, kingorna tamarmik.", source: "Kalaallisut", theme: .beginnings, subtheme: .whatAStartSettles),
        Passage(text: "Nanortalik: nannuttalik. Kalaallisut -lik pigisamik oqaaseqartarpoq, aterlu taamaalilluni nunap uumasui siuliini pillugit oqaluttuarpoq.", source: "Kalaallit Nunaat", theme: .beginnings, subtheme: .whatAStartSettles),
        Passage(text: "Kalaallit Nunaata avannaani seqineq ukiumut ataasiarluni aatsaat qaammaqqaartarpoq. Ulloq taanna nalliuttorsiorneqartarpoq, ukiorlu tamaat taassumannga naatsorsorneqarluni.", source: "Kalaallit Nunaat", theme: .beginnings, subtheme: .whatAStartSettles),

        // MARK: - Waiting
        Passage(text: "Kalaallisut -tsiiaq: suli suliarineqassasoq. Tikitsiiaq tassaavoq inuk angerlarnissaa utaqqineqartoq. Oqaaseq ataaseq utaqqisumik utaqqineqartumillu oqaluttuarpoq.", source: "Kalaallisut", theme: .waiting, subtheme: .heldBack),
        Passage(text: "Naatsiaq nunami masannermik peqartumi naasunngoqqusaanngilaq. Iluminiit unitsinneqarsimavoq, tamannalu allanngortinneqarsinnaavoq kiassuseq allanngoqqaarpat.", source: "Naasut", theme: .waiting, subtheme: .heldBack),
        Passage(text: "Umiatsiaat sikumit uninngatinneqartarput. Sikuisa aserornissaat utaqqineqartarpoq, aallarnissarlu inuit aalajangiisarnerinit pinngitsoorluni.", source: "Siku", theme: .waiting, subtheme: .heldBack),
        Passage(text: "Kalaallisut -tsiq-: aappaata suliaralugu utaqqineq. Utaqqineq oqaatsit iluanni inissaqarpoq, oqaasertatuinnaq atorlugu.", source: "Kalaallisut", theme: .waiting, subtheme: .heldBack),
        Passage(text: "Aput naatsiakkanik matuivoq. Ukiukkut aput naasunut kiassaataavoq, upernaakkullu aatserpat naatsiaqqanut imermik tunisisarluni.", source: "Naasut", theme: .waiting, subtheme: .heldBack),
        Passage(text: "Nunani issittuni orpiit annertusarnerat aputip ataani unitsinneqartarpoq. Ukiup ilaani ataasiinnaq naasarput, sinnerani uninngasarlutik.", source: "Naasut", theme: .waiting, subtheme: .heldBack),
        Passage(text: "Kalaallisut -nngitsoorpoq: pisussaagaluartoq pinngitsoq. Oqaaseq pisussaanerup pisunngitsuullu akornanni inissaqarpoq.", source: "Kalaallisut", theme: .waiting, subtheme: .heldBack),
        Passage(text: "Nanoq ukiumi qeriuppat sinilluinnanngilaq. Aalajaassuseq annikitsumik appartinneqarpoq, taamaalillunilu nanoq qaqugukkulluunniit makissinnaalluni.", source: "Uumasut", theme: .waiting, subtheme: .heldBack),
        Passage(text: "Kalaallisut -galuar-: taama pisimagaluartoq. Suligaluarpunga isumaqarpoq sulisimasunga, kisianni allamik akornuserneqarsimallunga.", source: "Kalaallisut", theme: .waiting, subtheme: .heldBack),
        Passage(text: "Immap ataani sikup annertunerpaartaa toqqorsimavoq. Sikoq qulaani takusaq annikitsuinnaavoq, aalanerali ataaniittunit aqunneqarluni.", source: "Siku", theme: .waiting, subtheme: .heldBack),
        Passage(text: "Puisi allumik utaqqisarpoq. Sikup ataani anersaartaarfiup eqqaani puisi qaqugukkulluunniit qulaanukarsinnaanngilaq allu matoqqappat.", source: "Uumasut", theme: .waiting, subtheme: .heldBack),
        Passage(text: "Kalaallisut oqaaseq ataaseq pisimasumik siunissamilu pisussamik ataatsikkut oqaluttuarsinnaavoq. Oqaatsit piffissamik nassuiaataqartuaannanngillat.", source: "Oqaatsit", theme: .waiting, subtheme: .heldBack),
        Passage(text: "Kalaallisut ukioq ataatsikkut ukiumik ukiullu ilaanik oqaluttuarpoq. Inuup ukiui naatsorsorneqarput ukiuunernik, aasarnernik pinnatik.", source: "Kalaallisut", theme: .waiting, subtheme: .theLongCount),
        Passage(text: "Qangarsuaq: ukiorpassuit matuma siorna. Kalaallisut -li ilanngunneqarpat qangarsuarlinngorpoq, tassa suli ungasinnerusoq.", source: "Kalaallisut", theme: .waiting, subtheme: .theLongCount),
        Passage(text: "Sermersuup ataani aput ukiuni 100.000-ni toqqorsimasoq suli takuneqarsinnaavoq. Ukiut tamarmik immikkut nalunaaqutaqarput, sermersuarlu atuagaatut atuarneqarsinnaalluni.", source: "Siku", theme: .waiting, subtheme: .theLongCount),
        Passage(text: "Sermeq ukiumut ataatsimut aallariaannaanngilaq. Ilaanni ulluinnarni meterinik arlalinnik ingerlasarpoq, ilaannilu ukiorpassuarni takussaanani.", source: "Siku", theme: .waiting, subtheme: .theLongCount),
        Passage(text: "Nalunaaqutaq: nalunnginnermut atortoq. Kalaallisut nalu- ilisimanngissutsimik oqaaseqarpoq, nalunaaqutarlu tassaalluni nalunnginnissamut ikiuutaasoq.", source: "Kalaallisut", theme: .waiting, subtheme: .theLongCount),
        Passage(text: "Kalaallit Nunaanni avannaani seqineq qaammatini arlalinni takussaanngilaq. Ukioq unnuartut naatsorsorneqarpoq, ullorlu ataaseq aatsaat qaammatit qaangiuppata utertarluni.", source: "Kalaallit Nunaat", theme: .waiting, subtheme: .theLongCount),
        Passage(text: "Nunap qaava sermersuup oqimaassusaanit ammut naqinneqarsimavoq. Sermeq aatsersimagaluarpat nuna suli ukiuni tusintilinni qummut nuutaassaaq.", source: "Nuna", theme: .waiting, subtheme: .theLongCount),
        Passage(text: "Ukiuni 4.500-ni matuma siorna inuit siulliit Kalaallit Nunaannut tikipput. Nunaqartut arlaqartut kingorna peqarunnaarsimapput, allallu tikilerlutik.", source: "Kalaallit Nunaat", theme: .waiting, subtheme: .theLongCount),
        Passage(text: "Kalaallisut -nikuu-: ilaanni pisimasoq. Qaqortumiinnikuuvunga isumaqarpoq Qaqortumi ilaanni najugaqarsimasunga, qanga nalunngikkaluarlugu.", source: "Kalaallisut", theme: .waiting, subtheme: .theLongCount),
        Passage(text: "Orpik mikisoq Kalaallit Nunaanni ukiuni untritilinni naasimasinnaavoq. Ilusaa mikisuugaluartoq ukiui inuup ukiuinit amerlanerupput.", source: "Naasut", theme: .waiting, subtheme: .theLongCount),
        Passage(text: "Kalaallisut kisitsisit inuup timaanik naatsorsorneqarput. Qulit assammi, arfineq aappaani, aqqaneq isigaani, inuup naallugu tassaalluni 20.", source: "Kisitsisit", theme: .waiting, subtheme: .theLongCount),
        Passage(text: "Immap ataaniittut ilaat ukiuni untritilinni inuusarput. Uumasut taakkua ilaat suli inuupput qallunaat Kalaallit Nunaannut tikinnginnerini.", source: "Imaq", theme: .waiting, subtheme: .theLongCount),
        Passage(text: "Kalaallisut tikkuaatit imaanut isiginnaartumut tunngavipput. Oqartoq imaap qaaninnut saatsisimavoq, qaqqallu tunuani inissisimallutik.", source: "Kalaallisut", theme: .waiting, subtheme: .standingAndWatching),
        Passage(text: "Kalaallisut samani: imaap qaaniittoq. Oqaaseq ataaseq ungasissusermik sammisamillu ataatsikkut oqaluttuarpoq, tikkuaanertut ittumik.", source: "Kalaallisut", theme: .waiting, subtheme: .standingAndWatching),
        Passage(text: "Kalaallisut kanani: ammut, imaap tungaanut. Pikani: qummut, nunap timaata tungaanut. Sammivik oqartup inissisimaneranit aallaaveqarpoq.", source: "Kalaallisut", theme: .waiting, subtheme: .standingAndWatching),
        Passage(text: "Tunumi tikkuaatit sammiviisa isumaat allanngorput. Imaq kangimut inissisimammat oqaatsit qiterutaannik allanngortitsivoq.", source: "Kalaallisut", theme: .waiting, subtheme: .standingAndWatching),
        Passage(text: "Piniartoq allup eqqaani nikuippoq. Puisip anersaartaarnera tusarpat aatsaat aalasarpoq, taassumalu siornagut nikuittuinnarluni.", source: "Piniarneq", theme: .waiting, subtheme: .standingAndWatching),
        Passage(text: "Sila isiginnaarneqartuaannarpoq. Nuiat, anori sikullu isiginnaarlugit ullumi qanoq innissaa nalunaarsorneqarsinnaavoq, aallarnissaq aalajangerneqarluni.", source: "Sila", theme: .waiting, subtheme: .standingAndWatching),
        Passage(text: "Kalaallisut -palaaq: tusarneqarsinnaavoq arlaannik pisoqartoq. Oqaasertaq taanna tusaamaneq isiginnaarnerlu avissaarterpai.", source: "Kalaallisut", theme: .waiting, subtheme: .standingAndWatching),
        Passage(text: "Qulaani nuiat sikup qaqortuanik tarrarsuuteqartarput. Imaq ammasoq nuianik qernertunik takutitsisarpoq, angalasullu ungasissumit aqqutissaminnik takusinnaallutik.", source: "Sila", theme: .waiting, subtheme: .standingAndWatching),
        Passage(text: "Nattoralik qaqqap qaavani unittarpoq. Isai inummit sisamariaammik pitsaanerupput, ungasissumilu uumasumik takusinnaalluni.", source: "Timmissat", theme: .waiting, subtheme: .standingAndWatching),
        Passage(text: "Kalaallisut ta(C)- oqaatsimut siuliusartoq oqaluttuami eqqaaneqareersumut innersuussivoq. Oqaaseq taanna paasititsivoq oqartoq tikkuaannaanngitsoq.", source: "Kalaallisut", theme: .waiting, subtheme: .standingAndWatching),
        Passage(text: "Qimmit qamutit siorna nikuipput. Ingerlanngikkallarmata anersaartaarnerat kisiat tusarneqartarpoq, aputillu nipaa suli aallartinngilaq.", source: "Piniarneq", theme: .waiting, subtheme: .standingAndWatching),
        Passage(text: "Ilulissat kangerluat ilulissanik ulikkaarpoq. Iluliaq ataaseq immami sivisuumik uninngasarpoq unittarfimmi, tullianillu kajumissaarneqartuni.", source: "Kalaallit Nunaat", theme: .waiting, subtheme: .standingAndWatching),
        Passage(text: "Aqisseq ukiukkut qaqortuuvoq, aasakkullu kajortuulluni. Qalipaataa allanngortarpoq apummik nalunaaqutsersorneqarnermik pinnagu, ullup takissusaanik malinnaalluni.", source: "Timmissat", theme: .waiting, subtheme: .standingAndWatching),

        // MARK: - Renewal
        Passage(text: "Kalaallisut -qqik-: uterluni. Oqaqqippoq isumaqarpoq oqaaseq nutaamik oqarneqartoq, aallaqqaataali puiorneqarani.", source: "Kalaallisut", theme: .renewal, subtheme: .cutAndComeAgain),
        Passage(text: "Tuttup nassui ukiumut ataasiarlutik nakkartarput. Nutaat naammassinerini annerulaartarput, uumasorlu ukiuni tamani nassuminik nutaanik pilersortarluni.", source: "Uumasut", theme: .renewal, subtheme: .cutAndComeAgain),
        Passage(text: "Orpik mikisoq nunami aserorterneqarsimasumi tunuanit naaqqittarpoq. Kikiakkat ataani uninngasut suli inuupput, qulaaniittulli peerneqarsimallutik.", source: "Naasut", theme: .renewal, subtheme: .cutAndComeAgain),
        Passage(text: "Timmissat suluinik nutaanik ukiumut ataasiarlutik pilersortarput. Sulut nutaat tikeriarpata timmissat qaammatit arlallit ingerlaarunnaartarput.", source: "Timmissat", theme: .renewal, subtheme: .cutAndComeAgain),
        Passage(text: "Kalaallisut -qattaar-: qaqugukkulluunniit uteqqilluni. Oqaasertaq taanna suliaq ataasiinnaanngitsoq amerlanertigullu pisartoq nassuiaataavoq.", source: "Kalaallisut", theme: .renewal, subtheme: .cutAndComeAgain),
        Passage(text: "Sikoq ukiumut ataatsimut nutaamik pilersittarpoq. Aasakkut peerneqartoq ukiakkut utertarpoq, sikorlu tamarmi ukiumi ataatsimi inuusarluni.", source: "Siku", theme: .renewal, subtheme: .cutAndComeAgain),
        Passage(text: "Qajaq amimik matoqqasarpoq. Ami ukiuni arlalinni atorneqareerpat taarserneqartarpoq, saneraalu suli aallaqqaataaninngaanniit atorneqartuarluni.", source: "Piniarneq", theme: .renewal, subtheme: .cutAndComeAgain),
        Passage(text: "Puisit amii inuit atisaannut ukiumut ataasiarlutik nutarterneqartarput. Atisaq ataaseq ukiumi ataatsimi atorneqarpoq, kingorna allanngortinneqarluni.", source: "Piniarneq", theme: .renewal, subtheme: .cutAndComeAgain),
        Passage(text: "Nunami issittumi nunap qaava aserorterneqarpat maniit siulliusumik utertarput. Naasut annertuut kingullerpaanngorlutik uterlutik.", source: "Naasut", theme: .renewal, subtheme: .cutAndComeAgain),
        Passage(text: "Kalaallisut -ssaar-: unittoq. Oqaasertaq taanna suliaq unippoq nassuiaataavoq, unitsinneralu qaqugukkulluunniit isumaqanngilaq naammassinermik.", source: "Kalaallisut", theme: .renewal, subtheme: .cutAndComeAgain),
        Passage(text: "Ammassaat ukiumut ataasiarlutik sinaanut tikittarput. Immap sineriaani mannillutik kingorna aallartarput, ukiullu tullianik uterlutik.", source: "Aalisarneq", theme: .renewal, subtheme: .cutAndComeAgain),
        Passage(text: "Sinaani naasut sikup peernerata kingorna sapaatit akunneri marluk qaangiuppata naapput. Piffissaq amigaataavoq, naasullu taamaattumik sukkasuutigisumik naasarlutik.", source: "Naasut", theme: .renewal, subtheme: .cutAndComeAgain),
        Passage(text: "Kalaallisut ukiup ilai sisamaapput: upernaaq, aasaq, ukiaq ukiorlu. Ukioq oqaatsimi ataatsimi ukiup ilaanik ukiullu naannerinik oqaluttuarpoq.", source: "Kalaallisut", theme: .renewal, subtheme: .theTurningYear),
        Passage(text: "Upernaakkut timmissat Kalaallit Nunaannut tikittarput. Ilaat nunarsuup aappaaninngaanniit tikipput, aallaavillu ataatsimut ukiumut tulliuttumut uterlutik.", source: "Timmissat", theme: .renewal, subtheme: .theTurningYear),
        Passage(text: "Upernavik: upernaarfik. Kalaallisut -vik atugaqarfimmik oqaaseqartarpoq, aterlu taanna nunap ukiumi ilaanik pillugu oqaluttuarpoq.", source: "Kalaallit Nunaat", theme: .renewal, subtheme: .theTurningYear),
        Passage(text: "Ukiakkut imaq sineriammi siulliusumik qeriuppoq, kingornagullu avataani. Sikoq taamaalilluni sineriammit aallartittarpoq, ukiullu sinaanit ingerlaartuarluni.", source: "Siku", theme: .renewal, subtheme: .theTurningYear),
        Passage(text: "Aasaq Kalaallit Nunaanni naammattuinnaavoq. Naasut qaammatini pingasuni naapput, mannillu timmissat taamatut sukkasuutigisumik piaqqiortarlutik.", source: "Naasut", theme: .renewal, subtheme: .theTurningYear),
        Passage(text: "Seqineq avannaani qaammatini arlalinni tarrinngilaq. Aasap qeqqani unnuaq ullorlu assigiipput, inuillu sinittarnerat allanngortarluni.", source: "Kalaallit Nunaat", theme: .renewal, subtheme: .theTurningYear),
        Passage(text: "Kalaallisut -siorpoq: ukiumi ilaanik nalliuttorsiorneq. Oqaasertaq taanna angalanermik nalliuttorsiornermillu ataatsikkut oqaluttuarpoq.", source: "Kalaallisut", theme: .renewal, subtheme: .theTurningYear),
        Passage(text: "Nanoq aasakkut sikoqanngippat nunami uninngasarpoq. Sikup utineranik utaqqisarpoq, ukiullu ilaa taanna nannup nerisaqarfianngorluni.", source: "Uumasut", theme: .renewal, subtheme: .theTurningYear),
        Passage(text: "Kalaallisut oqaatsit ukiuinik oqaluttuartut arlaqarput. Ukiaq, ukiakkut, ukiorlu ataatsimut atapput, oqaatsillu ukiup naanera aallartinneralu ataatsimut inissippaat.", source: "Kalaallisut", theme: .renewal, subtheme: .theTurningYear),
        Passage(text: "Aput ukiumut ataatsimut qaqortuunngorpoq, aasakkullu peertarluni. Nunap qalipaataa qaammatit qulinut ataasiarluni allanngortarpoq.", source: "Sila", theme: .renewal, subtheme: .theTurningYear),
        Passage(text: "Savaatillit Kujataani savaminnik ukiakkut nunamut aallartitsisarput. Savat ukiukkut illuni uninngasarput, upernaakkullu qaammatit tallimat qaangiuppata anisillutik.", source: "Kalaallit Nunaat", theme: .renewal, subtheme: .theTurningYear),
        Passage(text: "Aasivik: aasarfik. Kalaallit ilaqutariit aasakkut ataatsimut katersuuttarput, ukiakkullu avissaarlutik. Ateq ataaseq piffissamik inissamillu ataatsikkut oqaluttuarpoq.", source: "Kalaallit Nunaat", theme: .renewal, subtheme: .theTurningYear),
        Passage(text: "Kalaallisut ajorpoq ajunngilarlu: ajorpoq ajortumik oqaaseqarpoq, ajunngilaq taassuma naggasersorneqarnera. Pitsaassuseq oqaatsimi ajortup naapertuutinngineranik nassuiarneqarpoq.", source: "Kalaallisut", theme: .renewal, subtheme: .madeWhole),
        Passage(text: "Kalaallisut -lluar-: pitsaasumik. Inuulluarit tassaavoq inuunerit pitsaassaaq, aammalu kalaallit inuulluaqqusaataat.", source: "Kalaallisut", theme: .renewal, subtheme: .madeWhole),
        Passage(text: "Kalaallit oqaluttuaanni Sassuma Arnaa immap ataani najugaqarpoq. Nussui aaqqissuunneqarpata uumasut immamut utertarput, angakkorlu taassumunnga aqqartarluni.", source: "Kalaallit oqaluttuaat", theme: .renewal, subtheme: .madeWhole),
        Passage(text: "Qajaq amimik aserortumik amermik nutaamik amerneqartarpoq. Sanaartortoq ammip aserornera puiorneqassanngitsutut isumaqarpoq, qajarli suli qajaavoq.", source: "Piniarneq", theme: .renewal, subtheme: .madeWhole),
        Passage(text: "Kalaallisut qasuersaarpoq: nukissat utertarput. Oqaaseq qasunermik unitsitsinermillu oqaluttuarpoq, sinnerneqarnermik pinnagu.", source: "Kalaallisut", theme: .renewal, subtheme: .madeWhole),
        Passage(text: "Sikup aserorsimasup ilai nutaamik ataqatigiissarput. Ukiukkut sikoq ataatsimoortarpoq, aserornerata nalunaaqutai suli takussaallutik.", source: "Siku", theme: .renewal, subtheme: .madeWhole),
        Passage(text: "Uumasup kiassusia issittumi qaammatit arlallit annikitsumik appartinneqarsinnaavoq. Uumasoq kingorna nukittusartarpoq, allanngortitalli tamaasa utertarlugit.", source: "Uumasut", theme: .renewal, subtheme: .madeWhole),
        Passage(text: "Kalaallisut -junnaar-: pinngorunnaartoq. Oqaasertaq taanna suliap naanera nassuiaataavoq, isumaqanngitsorlu pisimasup ajortuuneranik.", source: "Kalaallisut", theme: .renewal, subtheme: .madeWhole),
        Passage(text: "Puisip amia orsumik saliineqarpat qillaraluni nutaanngortarpoq. Suliaq taanna arnat ilinniagaraat, atisarlu taamaalilluni ukiuni amerlasuuni atorneqarsinnaalluni.", source: "Piniarneq", theme: .renewal, subtheme: .madeWhole),
        Passage(text: "Nunami aserorterneqarsimasumi ivikkat siulliusumik utertarput. Nunap qaava taakkunannga nutaamik pilersinneqarpoq, naasullu allat kingorna tikilerlutik.", source: "Naasut", theme: .renewal, subtheme: .madeWhole),
        Passage(text: "Kalaallisut alianaappoq alianaarlu assigiinngillat. Alianarpoq aliasunnermik oqaaseqarpoq, alianaak tusarneqarpat nuannaarnermik oqaaseqartarluni.", source: "Kalaallisut", theme: .renewal, subtheme: .madeWhole),
        Passage(text: "Immami sikoq aserorpat imaq qaammaqqippoq. Naasut mikisut immap qaavani sapaatit akunneri arlallit qaangiuppata amerliartortarput, imarmiullu taakkuninnga nerisaqarlutik.", source: "Imaq", theme: .renewal, subtheme: .madeWhole),
        Passage(text: "Nunami eqqissisimatitami uumasut namminneq ikiliartornerminnik unitsitsisarput. Nuna taanna nunarsuarmi annerpaavoq, inuillu taassumani najugaqanngillat.", source: "Kalaallit Nunaat", theme: .renewal, subtheme: .madeWhole),

        // MARK: - Light
        Passage(text: "Kalaallisut ullaaq, ulloq, unnuk unnuarlu ullup avissaarutaanik oqaluttuarput. Ullup ilai qaammarnermik allanngortarnermik nalunaarsorneqarput, nalunaaqutamik pinnagit.", source: "Kalaallisut", theme: .light, subtheme: .theEdgesOfTheDay),
        Passage(text: "Kalaallit Nunaanni avannaani unnuap ullullu akornata takineqarpoq. Seqinerup nuinera qaammatit sisamat qaangiuppata pisarpoq, ullullu tulliani sivikitsuinnaanngorluni.", source: "Kalaallit Nunaat", theme: .light, subtheme: .theEdgesOfTheDay),
        Passage(text: "Seqineq Kalaallit Nunaanni avannaani ukiakkut kingullermik tarrittarpoq. Ulloq taanna nunaqarfinni nalunaarsorneqartarpoq, inuillu qaammaqqutinik ikitsisarlutik.", source: "Kalaallit Nunaat", theme: .light, subtheme: .theEdgesOfTheDay),
        Passage(text: "Aasap qeqqani seqineq issittumi tarrinngilaq. Unnuaq qaammaruteqanngitsoq inunnut nunami allami inuusunut ilisimaneqanngilaq.", source: "Qilak", theme: .light, subtheme: .theEdgesOfTheDay),
        Passage(text: "Kalaallisut oqaaseq qaamaneq oqaaseq qaammat ataatsimut atapput. Qaammat qilammi qaamasoq ukiullu ilaa ataatsikkut taaguutaapput.", source: "Kalaallisut", theme: .light, subtheme: .theEdgesOfTheDay),
        Passage(text: "Sikup qaavani seqinerup nuinera unnuup naanerata siorna qaammarnermik aappalaartumik pilersitsisarpoq. Qalipaat taanna minutsini arlalinni kisiat takussaasarpoq.", source: "Sila", theme: .light, subtheme: .theEdgesOfTheDay),
        Passage(text: "Timmissat ullaakkut siulliusumik erinarsortarput. Erinarsornerat seqinerup nuinnginnerani aallartissarpoq, taamaalillunilu ullup aallartinnera nipimik nalunaarsorneqarluni.", source: "Timmissat", theme: .light, subtheme: .theEdgesOfTheDay),
        Passage(text: "Naasut ilaat unnuap takissusaanik uuttortaasarput. Qaamanerup pinnagu taarsiornerup takissusaa naasumut nalunaaqutaavoq naanissamut.", source: "Naasut", theme: .light, subtheme: .theEdgesOfTheDay),
        Passage(text: "Kalaallisut ullaakkorsiorpoq ullaakkut nerinermik oqaaseqarpoq. Oqaaseq ullup ilaanik nerinermillu ataatsikkut oqaluttuarpoq, oqaatsit marluk pinnagit.", source: "Kalaallisut", theme: .light, subtheme: .theEdgesOfTheDay),
        Passage(text: "Ukiukkut Kalaallit Nunaanni ulloq qaammarissoq ilaanni nalunaaqutaq ataaseq kisiat sivisussuseqarpoq. Nunaqarfinni inuit taava ullut naapertorlugit sulisarput.", source: "Kalaallit Nunaat", theme: .light, subtheme: .theEdgesOfTheDay),
        Passage(text: "Aput seqinerup qaamaneranik amerlanertigut utertitsisarpoq. Ukiukkut ullup qaamanera aputip qaavanit qummut utertinneqarpoq, silarlu qaammanerulersarluni.", source: "Sila", theme: .light, subtheme: .theEdgesOfTheDay),
        Passage(text: "Qaammat sikup qaavani aqqusineq qaqortoq takutittarpoq. Angalasut aqqusinerup malinnaarnerata nalaani nunaqarfimmut aqqutissaminnik nassaarisinnaapput.", source: "Qilak", theme: .light, subtheme: .theEdgesOfTheDay),
        Passage(text: "Nuiat qernertut immamit ammasumit tarrarsuutigineqartarput. Angalasoq qilammut isigalunilu immap ammanera ungasissumit nalunaarsorsinnaavaa.", source: "Sila", theme: .light, subtheme: .readingTheLight),
        Passage(text: "Sikup qaqortua nuianut qaammarnermik utertitsisarpoq. Qilaap qaqortua sikumik nalunaaqutaavoq, qernertorlu imaanik ammasunik.", source: "Siku", theme: .light, subtheme: .readingTheLight),
        Passage(text: "Kalaallisut oqaaseq qaammarpoq qaammarissumik oqaaseqarpoq. Silap qaamanera uumasunut naasunullu piffissamik nalunaarsuutaavoq, nalunaaqutaq pinnagu.", source: "Kalaallisut", theme: .light, subtheme: .readingTheLight),
        Passage(text: "Naasut Kalaallit Nunaanni unnuap takissusaanik naanissaminnut nalunaarsuuteqarput. Qaamanerup sivisussusia uuttortarneqarpoq, kiassuserlu pinnagu.", source: "Naasut", theme: .light, subtheme: .readingTheLight),
        Passage(text: "Ilulissat qaqortuut seqinerup qaamaneranik utertitsisarput. Iluliaq tungujortoq sivisuumik immami uninngasimavoq, aalu qeriuppat qaqortuunngorluni.", source: "Siku", theme: .light, subtheme: .readingTheLight),
        Passage(text: "Aput nutaaq seqinerup qaamaneranit 90 procentit utertippai. Immap qaava ammasoq taamaallaat annikitsuinnarmik utertitsisarpoq, kiassusiallu allanngorlutik.", source: "Sila", theme: .light, subtheme: .readingTheLight),
        Passage(text: "Timmissat ilaat qilammi qaamanerup ingerlanera takusinnaavaat inunnit takussaanngitsoq. Timmissat taamaalilluni seqineq nuiat tunuanniikkaluartoq nassaarisinnaavaat.", source: "Timmissat", theme: .light, subtheme: .readingTheLight),
        Passage(text: "Kalaallisut sila silarsuarmillu ataatsimut atapput. Sila silap pissusianik, avatangiisinik silatussutsimillu ataatsikkut oqaluttuarpoq.", source: "Kalaallisut", theme: .light, subtheme: .readingTheLight),
        Passage(text: "Imaq qaammarissoq sikup ataani suli qaamavoq. Naasut mikisut sikup ataani inuupput, qaamanerup annikitsup nalaani nerisassaminnik pilersitsillutik.", source: "Imaq", theme: .light, subtheme: .readingTheLight),
        Passage(text: "Puisit isaat imaani taarsiortumi takusinnaapput. Isaasa iluini qaamaneq utertinneqartarpoq, taamaalillunilu qaamaneq marloriaammik atorneqarluni.", source: "Uumasut", theme: .light, subtheme: .readingTheLight),
        Passage(text: "Angalasut sikup qalipaataanik ilisimasaqarnermikkut sikup issussusia nalunaarsorsinnaavaat. Sikoq tungujortoq nutaavoq salluulluni, qaqortorlu nukittooq.", source: "Siku", theme: .light, subtheme: .readingTheLight),
        Passage(text: "Nuiat sikumut qanittut ammut nalunaarsuuteqartarput. Sikup qaava qaammarissoq nuianut utertinneqartarpoq, angalasullu ungasissumit paasisinnaallugu suna siornatigut inissisimasoq.", source: "Sila", theme: .light, subtheme: .readingTheLight),
        Passage(text: "Arsarnerit: qilammi arsattartut. Kalaallit oqaluttuaanni toqusut tarnii qilammi arsattarput, qaamanerlu taakkua aalanerinit pinngortoq.", source: "Kalaallit oqaluttuaat", theme: .light, subtheme: .lightItself),
        Passage(text: "Qulleq: ikumaffik. Ujaqqamik saviminertamik sanaajuvoq, puisip orsuanik ikumatitaqarluni, ikuallattarfialu maniinnik suputinilluunniit sananeqarluni.", source: "Kalaallit Nunaat", theme: .light, subtheme: .lightItself),
        Passage(text: "Qulleq illumi qaammaqqutaavoq kiassaataalluni. Aputip aannerani, nerisassat uunneranni atisallu panernerini atorneqartarpoq, illullu atortuinit pingaarnerpaajulluni.", source: "Kalaallit Nunaat", theme: .light, subtheme: .lightItself),
        Passage(text: "Ulloriaq: qilammi qaamasoq. Kalaallisut oqaaseq ullup oqaasianut atavoq, unnuallu qaamanerata ullormik taaguutaqarluni.", source: "Ulloriaat", theme: .light, subtheme: .lightItself),
        Passage(text: "Seqineq: ullup qaamanera. Kalaallit oqaluttuaanni seqineq qaammallu qatanngutigiipput, qilammullu qimaallutik.", source: "Kalaallit oqaluttuaat", theme: .light, subtheme: .lightItself),
        Passage(text: "Arsarnerit qutsissusermi 100 kilometerinit 300-nut annerusumi pinngortarput. Qaamanerup qalipaataa qanoq issusaanit aallaaveqarpoq, qorsooq nitrogenimik pinngortitaavoq.", source: "Qilak", theme: .light, subtheme: .lightItself),
        Passage(text: "Immap ataani uumasut ilaat namminneq qaammaqqutiginnittarput. Taarsiortumi qaamaneq taanna aappariinnermut nerisassarsiornermullu atorneqarpoq.", source: "Imaq", theme: .light, subtheme: .lightItself),
        Passage(text: "Kalaallisut qaammat qilammi qaamasumik ukiullu ilaanik ataatsikkut taaguuteqarpoq. Piffissaq qaamanerulli nalunaarsorneqartarpoq, oqaatsimi ataatsimi katinneqarlutik.", source: "Kalaallisut", theme: .light, subtheme: .lightItself),
        Passage(text: "Ikumatitaq maniinnik sananeqartoq unnuaq naallugu ikumasinnaavoq. Arnat ikumatitat qaammarnerannik aqutsisarput, qullerlu taamaalilluni illup nipaanngorluni.", source: "Kalaallit Nunaat", theme: .light, subtheme: .lightItself),
        Passage(text: "Ilulissat seqinerup qaamaneranik iluminnit qaammartitsisutut ipput. Iluliup iluani qaamaneq tungujortumik allanngortarpoq, sikup ukiuni amerlasuuni oqimaatsuunerata kingunerisaanik.", source: "Siku", theme: .light, subtheme: .lightItself),
        Passage(text: "Kalaallisut qaammarpoq qaamavorlu assigiinngillat. Siulleq allanngornermik oqaaseqarpoq, aappaa qanoq innermik, oqaatsillu marluk tunngavimmik ataatsimik atorlutik.", source: "Kalaallisut", theme: .light, subtheme: .lightItself),
        Passage(text: "Nuiat sikup qaavaniittut ullaakkut aappalaartarput. Qaamaneq silap kissarsuanit ingerlaartoq nuianut agguarneqarpoq, qilaallu taamaalilluni aappalaartuunngorluni.", source: "Sila", theme: .light, subtheme: .lightItself),

        // MARK: - Pattern
        Passage(text: "Kalaallisut kisitsisit: ataaseq, marluk, pingasut, sisamat, tallimat. Tallimat assammi ataatsimi naapput, kisitsinerlu assammut aappaanut nuuttarluni.", source: "Kisitsisit", theme: .pattern, subtheme: .counted),
        Passage(text: "Arfineq-ataaseq: assammi aappaani ataaseq. Kalaallisut kisitsisit arfinilinniit assammut aappaanut atapput, arfineq-marluk arfineq-pingasullu malissullugit.", source: "Kisitsisit", theme: .pattern, subtheme: .counted),
        Passage(text: "Qulingiluat: qulinit ataaseq amigaataasoq. Kisitsit taanna qulinit aallaaveqarpoq, ammulli naatsorsorneqarluni, tassalu 9.", source: "Kisitsisit", theme: .pattern, subtheme: .counted),
        Passage(text: "Aqqaneq: isigaani aallartitsineq. Qulit assatit naammassippata kisitsineq isigannut aqqartarpoq, aqqaneq-marluk aqqaneq-pingasullu malissullugit.", source: "Kisitsisit", theme: .pattern, subtheme: .counted),
        Passage(text: "Inuup naallugu: 20. Kalaallisut kisitsisit inuup assai isigaalu naapertorlugit aaqqissuunneqarput, kisitsitsillu annerpaaq inuk naammalluinnartoq.", source: "Kisitsisit", theme: .pattern, subtheme: .counted),
        Passage(text: "Ullumikkut kalaallisut kisitsisit 12-mut atorneqarput, taakkunanngalu qaangiuppata qallunaatut kisitsisit atorneqartarlutik. Kisitsisit pisoqqat suli ilisimaneqarput.", source: "Kisitsisit", theme: .pattern, subtheme: .counted),
        Passage(text: "Kalaallisut oqaasertat 400-nit 500-nut amerlassuseqarput, naggasersuutillu 318-it. Oqaaseq ataaseq taakkunannga arlalinnik ilaqarsinnaavoq.", source: "Oqaatsit", theme: .pattern, subtheme: .counted),
        Passage(text: "Kalaallisut naggasersuutit ataatsimut 648-nik amerlassuseqarsinnaapput. Amerlassuseq taanna inuit arfineq-marluit oqaluttuallu ilusaasa qulingiluat katinnerinit pinngorpoq, ilaalli atorneqanngillat.", source: "Oqaatsit", theme: .pattern, subtheme: .counted),
        Passage(text: "Kalaallisut oqaaseq ataaseq pingasunit tallimanut oqaasertaqartarpoq. Arfinilinnit amerlanerusut naammattumik atorneqartarput, kisianni ilaanniinnaq.", source: "Oqaatsit", theme: .pattern, subtheme: .counted),
        Passage(text: "Kalaallisut nipit taakkua kisiat pingasuupput: a, i, u. E aamma o allanneqartarput, kisianni nipit taakkua allat marluk eqqaanniitillugit.", source: "Kalaallisut", theme: .pattern, subtheme: .counted),
        Passage(text: "Kalaallisut oqaluttuap ilusai qulingiluupput. Ilaat oqaluttuamik naammassisumik pilersitsisinnaapput, allalli oqaluttuap ilaanut kisimik atorneqarsinnaallutik.", source: "Oqaatsit", theme: .pattern, subtheme: .counted),
        Passage(text: "Kalaallisut naggasersuutit arfineq-marluk nunami inissamik ingerlanermillu oqaluttuarput. Oqaatsit akornanni oqaaseq inissamik oqaluttuartoq peqanngilaq, naggaseq kisimi taamaaliortoq.", source: "Oqaatsit", theme: .pattern, subtheme: .counted),
        Passage(text: "Kalaallisut nipit marluinnaat naapittarput, pingasut ataatsimut atanngillat. Malittarisassaq taanna oqaatsini takisorujussuarni tamani atuuppoq.", source: "Kalaallisut", theme: .pattern, subtheme: .fittedTogether),
        Passage(text: "Kalaallisut oqaasertat naapinnerini nipit allanngortarput. Oqaasertaq ataaseq ilusiligaanni pingasunik sisamanillu ilusilerneqarsinnaavoq, isumaali allanngunani.", source: "Oqaatsit", theme: .pattern, subtheme: .fittedTogether),
        Passage(text: "Kalaallisut oqaaseq ataaseq tuluttut oqaluttuaq tamarmi inissinneqarsinnaavoq, oqaasertalli tulleriissaarnerat allarpasippoq. Kingullersaq siullersaanngortarpoq.", source: "Oqaatsit", theme: .pattern, subtheme: .fittedTogether),
        Passage(text: "Qamutit sanaajupput sinnermik qilertuinernik, kikiatsertakkanik pinnagit. Qamutit taamaalilluni sikup manngertup qaavani aalasinnaapput aserornatik.", source: "Piniarneq", theme: .pattern, subtheme: .fittedTogether),
        Passage(text: "Qajaap saneraa saarnernik qisunnilluunniit qilertuineqarluni sananeqartarpoq. Ilai tamarmik aalasinnaapput, qajarlu taamaalilluni malinnut naleqqussarsinnaalluni.", source: "Piniarneq", theme: .pattern, subtheme: .fittedTogether),
        Passage(text: "Aputip qerinerata ilusaa arfineq-ataatsinik saniliusaqarpoq. Qanik ataaseq allamut assingusoq nassaarineqarneq ajorpoq, ilusaali malittarisassaq ataaseq malillugu.", source: "Sila", theme: .pattern, subtheme: .fittedTogether),
        Passage(text: "Sikup aserornerani ilusai saniliusaqarput. Immap ataani sikup aallarnerani ilusaa nunami ujaqqat aserornerinut assingusarpoq, annertussusia allaanerungaluartoq.", source: "Siku", theme: .pattern, subtheme: .fittedTogether),
        Passage(text: "Illutoqqat ujaqqanik ivikkanillu sananeqartarput. Ujaqqat tulleriipput assigiinngitsutigut, ivigkarlu akornanni tunuartitsilluni, illulu taamaalilluni kissartuunngorluni.", source: "Kalaallit Nunaat", theme: .pattern, subtheme: .fittedTogether),
        Passage(text: "Timmissat qeqertani inissaqartitsipput assigiinnik ungasissuseqartunik. Timmiaq tamarmi aappani sikkeraatigut angussinnaasaanik ungasissuseqarpoq, pinngitsoorlugulu.", source: "Timmissat", theme: .pattern, subtheme: .fittedTogether),
        Passage(text: "Kalaallisut naggasersuutit oqaatsit naggataani inissapput, oqaasertallu siornagut. Inissineq allanngortinneqarpat oqaaseq isumaqarunnaartarpoq.", source: "Oqaatsit", theme: .pattern, subtheme: .fittedTogether),
        Passage(text: "Puisip amia atisanngortinneqarpat ilai qilertuinernik ataqatigiissinneqartarput. Imermik akuutissaqanngitsumik akuersaarneq arnat ilinniagaraat, atisarlu taamaalilluni imermik ilaanngitsuunngorluni.", source: "Piniarneq", theme: .pattern, subtheme: .fittedTogether),
        Passage(text: "Naasut mikisut nunami issittumi ataatsimoortumik naasarput. Naasut katillugit anorersuarnit illersorneqarput, ataasiakkaalli illersorneqarsinnaanngitsut.", source: "Naasut", theme: .pattern, subtheme: .fittedTogether),
        Passage(text: "Kalaallisut qarasaasiaq: qarasap assingusaa. Oqaaseq oqaatsinit marlunnit sananeqarpoq, atortorlu taamaalilluni kalaallisut atermik namminermik pissarsivoq.", source: "Kalaallisut", theme: .pattern, subtheme: .orderNamed),
        Passage(text: "Kalaallisut timmisartoq: timmisoq. Oqaaseq atortumik nassuiaanngilaq, kisianni suliaanik, atortullu taamaalilluni suliaminik ateqartinneqarluni.", source: "Kalaallisut", theme: .pattern, subtheme: .orderNamed),
        Passage(text: "Kalaallisut -usaq: allamut assingusoq. Naqinneq @ kalaallisut a-jusaq taaguutigineqarpoq, tassa a-mut assingusoq.", source: "Kalaallisut", theme: .pattern, subtheme: .orderNamed),
        Passage(text: "Kalaallisut -miut: inissami najugaqartut. Nuummiut, Paamiut, Sisimiut: nunaqarfiit aqqi inuit najugaqarfiannik oqaluttuarput, nunap kisimi pinnagu.", source: "Kalaallit Nunaat", theme: .pattern, subtheme: .orderNamed),
        Passage(text: "Ittoqqortoormiit: illutuut najugaqartut. Ateq oqaatsinit pingasunit sananeqarpoq, illoqarfiullu inui ateqartitaapput illuminnit.", source: "Kalaallit Nunaat", theme: .pattern, subtheme: .orderNamed),
        Passage(text: "Kalaallisut nunat aqqi oqaluttuarissaartarput. Kangerlussuaq: kangerluk angisooq. Qeqertarsuaq: qeqertaq angisooq. Uummannaq: uummatitut ittoq.", source: "Kalaallit Nunaat", theme: .pattern, subtheme: .orderNamed),
        Passage(text: "Ilulissat: iluliaq amerlanertut. Illoqarfiup atia kangerluup ilulissaanik oqaluttuarpoq, sermersuarlu ilulissanik nunarsuarmi amerlanerpaanik tunisisoq.", source: "Kalaallit Nunaat", theme: .pattern, subtheme: .orderNamed),
        Passage(text: "Aasiaat: aasiaat amerlanertut. Illoqarfiup atia uumasunik mikisunik oqaluttuarpoq, taakkualu qeqertani najugaqartut.", source: "Kalaallit Nunaat", theme: .pattern, subtheme: .orderNamed),
        Passage(text: "Sisimiut: sisip najugaani najugaqartut. Illoqarfiup atia uumasup nunami inissaanik oqaluttuarpoq, inuit najugaannik pinnagu.", source: "Kalaallit Nunaat", theme: .pattern, subtheme: .orderNamed),
        Passage(text: "Qaqortoq: qaqortoq. Maniitsoq: maniitsoq. Nunat aqqi qanoq issusiminnik nassuiaataapput, oqaluttuassartaminnik pinnagit.", source: "Kalaallit Nunaat", theme: .pattern, subtheme: .orderNamed),
        Passage(text: "Kalaallisut -lik: pigisalik. Nanortalik nannunik peqarpoq, aterlu taamaalilluni nunap uumasuinik nalunaarsuutaalluni.", source: "Kalaallit Nunaat", theme: .pattern, subtheme: .orderNamed),
        Passage(text: "Kalaallisut -liaq: sanaaq. Assiliaq assiliortakkaavoq, illuliarlu illuusoq sananeqarsimasoq. Oqaasertaq ataaseq sanaannermik nalunaarsuutaavoq.", source: "Kalaallisut", theme: .pattern, subtheme: .orderNamed),
        Passage(text: "Kalaallisut nalunaaqutaq: nalunnginnermut atortoq. Nalu- ilisimanngissutsimik oqaaseqarpoq, atortorlu taamaalilluni ilisimannginnermik akiuiisutut taaguuteqarluni.", source: "Kalaallisut", theme: .pattern, subtheme: .orderNamed),

        // MARK: - Ground
        Passage(text: "Kalaallisut nuna: nunarsuup qaava, nunaqarfik, nunarlu inuup pigisaa. Oqaaseq ataaseq isumanik pingasunik tigumiaavoq, avissaarutaanngitsunik.", source: "Kalaallisut", theme: .ground, subtheme: .theSoilItself),
        Passage(text: "Nunap qaava issittumi ukiuni tamani qerisuuvoq. Aasakkut qaavaa taamaallaat centimeterit qulit ataani aatsertarpoq, naasullu taakkuani kisimi naasinnaallutik.", source: "Nuna", theme: .ground, subtheme: .theSoilItself),
        Passage(text: "Sermersuup oqimaassusia nunap qaava ammut naqippaa. Sermeq aatserpat nuna ukiuni tusintilinni qummut utertarpoq, ullumikkullu suli nuunneq ingerlaartoq.", source: "Nuna", theme: .ground, subtheme: .theSoilItself),
        Passage(text: "Kalaallit Nunaanni ujarak nunarsuarmi utoqqaanerpaanut ilaavoq. Ujaqqat ilaat ukiuni milliardilinni pingasuni sisamanilluunniit uninngasimapput, nunap qaavatalu qaqugukkulluunniit allanngortitanngitsuunerinik takutitsillutik.", source: "Nuna", theme: .ground, subtheme: .theSoilItself),
        Passage(text: "Maniit nunap qaavani naasunut siulliupput. Ujaqqat qaavini naasarput, aserorterlugillu nunanngortitsisarlutik, naasullu allat kingorna taakkuani naasinnaalersarlutik.", source: "Naasut", theme: .ground, subtheme: .theSoilItself),
        Passage(text: "Kangerluk: sermerup qangali aserorterisimasaa. Immap ilaa nunap iluanut isersimasoq kangerlummik taaguuteqarpoq, Kalaallit Nunaatalu sinaani amerlaqisut.", source: "Nuna", theme: .ground, subtheme: .theSoilItself),
        Passage(text: "Kujataani nunap qaava savaatinut naammappoq. Nunap ilaa taanna Kalaallit Nunaanni ivikkanik amerlanerpaanik peqarpoq, aasarlu sinneranit sivisunerulluni.", source: "Kalaallit Nunaat", theme: .ground, subtheme: .theSoilItself),
        Passage(text: "Kalaallisut nunaqarfik: nunaqarfik. Oqaaseq nuna aamma -qar- -vik-lu katillugit sananeqarpoq, tassa nunamik peqarfik.", source: "Kalaallisut", theme: .ground, subtheme: .theSoilItself),
        Passage(text: "Aput nunap qaava ukiukkut illersorpaa. Aputip ataani kiassuseq nunarlu qerinngippat naasut kikiakkaat sapernartumik anniarfiuvoq, upernaarlu aatsaat pilertortumik naalersarlutik.", source: "Naasut", theme: .ground, subtheme: .theSoilItself),
        Passage(text: "Kalaallit Nunaanni nunap qaava annertunerpaartaa sermimik matoqqavoq. Sinaani nuna ammasoq taamaallaat qeqertatut ittumik takussaavoq, avataanilu immaq.", source: "Kalaallit Nunaat", theme: .ground, subtheme: .theSoilItself),
        Passage(text: "Qaqqat Kalaallit Nunaanni sermerup aserorterneranit ilusilerneqarsimapput. Qaqqap ilusaa sermerup ingerlanerata malinnaarnerata nalunaaqutaraa, ukiullu tusintit taakkunani takussaallutik.", source: "Nuna", theme: .ground, subtheme: .theSoilItself),
        Passage(text: "Naasut kikiakkaat nunami qerisumi ammut ingerlasinnaanngillat. Naasut taamaalilluni sanimut siaruarterisarput, ataatsimoortumillu nunap qaavani matuisarlutik.", source: "Naasut", theme: .ground, subtheme: .theSoilItself),
        Passage(text: "Kalaallisut -meerpoq: sumiit aggersoq. Nuumminngaanneerpoq isumaqarpoq Nuumminngaanniit tikittoq, oqaatsimi ataatsimi nunamik oqartumillu ataatsikkut oqaluttuarluni.", source: "Kalaallisut", theme: .ground, subtheme: .aPlaceYouAreFrom),
        Passage(text: "Kalaallisut -miut: najugaqartut. Inuk nunaminik ateqartinneqartarpoq, ateralu taanna oqaluttuarpoq sumi inuk aallaaveqarnersoq.", source: "Kalaallisut", theme: .ground, subtheme: .aPlaceYouAreFrom),
        Passage(text: "Nunarput utoqqarsuanngoravit.", source: "Henrik Lund, 1912", theme: .ground, subtheme: .aPlaceYouAreFrom),
        Passage(text: "Kalaallit Nunaat: kalaallit nunaat. Nunap atia inuinit aallaaveqarpoq, inuillu nunaminnit, taamaalillutik oqaaseq marloriaammik oqaluttuarluni.", source: "Kalaallit Nunaat", theme: .ground, subtheme: .aPlaceYouAreFrom),
        Passage(text: "Kalaallisut meeraagallarama isumaqarpoq meeraagallarnera. Oqaaseq ataaseq inuup ukiuinik siullernik oqaluttuarpoq, oqaatsit arlallit pinnagit.", source: "Kalaallisut", theme: .ground, subtheme: .aPlaceYouAreFrom),
        Passage(text: "Kalaallisut Kitaa, Tunu, Avannaa Kujataarlu nunap sinaanik sisamanik taaguutaapput. Tunu tunuliaqutaanik oqaaseqarpoq, tassa imaap tunuani inissisimasoq.", source: "Kalaallit Nunaat", theme: .ground, subtheme: .aPlaceYouAreFrom),
        Passage(text: "Nuuk: nuuk. Illoqarfiup atia nunap immamut isortaanik nassuiaataavoq, illoqarfiullu taamaalilluni nunap ilusaanik ateqartinneqarluni.", source: "Kalaallit Nunaat", theme: .ground, subtheme: .aPlaceYouAreFrom),
        Passage(text: "Kalaallisut inuk inuillu: inuk inummik oqaaseqarpoq, inuillu inuinnarnik. Oqaaseq nunani issittuni inuit tamarmik nammineq taaguutigisaat.", source: "Kalaallisut", theme: .ground, subtheme: .aPlaceYouAreFrom),
        Passage(text: "Nunaqarfimmi inuit 50-t najugaqarsinnaapput. Inuit tamarmik tamanit ilisarineqarput, nunaqarfiullu atia inuup ateranut ilanngunneqartarluni.", source: "Kalaallit Nunaat", theme: .ground, subtheme: .aPlaceYouAreFrom),
        Passage(text: "Paamiut: paap eqqaani najugaqartut. Ateq kangerluup paavanik oqaluttuarpoq, inuillu taakkani najugaqartut kangerluup atianik ateqartinneqarlutik.", source: "Kalaallit Nunaat", theme: .ground, subtheme: .aPlaceYouAreFrom),
        Passage(text: "Inuit siulliit Kalaallit Nunaannut ukiut 4.500-t matuma siorna tikipput. Inuit taakkua nunap avannaatungaatigut tikipput, sinaakkullu ammut ingerlaartarlutik.", source: "Kalaallit Nunaat", theme: .ground, subtheme: .aPlaceYouAreFrom),
        Passage(text: "Kalaallisut sumiuuneq apeqqutaassaaq. Sumiuuvit apeqqutigineqarpat inuup nunaminik akisarpaa, illoqarfimminik pinnagu.", source: "Kalaallisut", theme: .ground, subtheme: .aPlaceYouAreFrom),
        Passage(text: "Nuna eqqissisimatitaq: nuna eqqissineq pillugu illersorneqartoq. Kalaallit Nunaanni avannaani nuna taamaattoq nunarsuarmi annerpaavoq, taamaattumillu inuit tassani najugaqanngillat.", source: "Kalaallit Nunaat", theme: .ground, subtheme: .aKeptPlace),
        Passage(text: "Kalaallisut -vik: suliffik imaluunniit atugaqarfik. Nerrivik nerriffiuvoq, siniffik siniffiuvoq, igaffillu igaffiulluni. Oqaasertaq ataaseq inissamik piffissamillu ataatsikkut oqaluttuarpoq.", source: "Kalaallisut", theme: .ground, subtheme: .aKeptPlace),
        Passage(text: "Naatsiiveq Kalaallit Nunaanni Kujataani atorneqartarpoq. Naatsiivinni naatsiiat qaammatini pingasuni naapput, ukiullu sinnerani nunap qaava qerisarluni.", source: "Kalaallit Nunaat", theme: .ground, subtheme: .aKeptPlace),
        Passage(text: "Panertitsivik illup eqqaani nikorfasarpoq. Aalisagaq puisillu neqaat anorimut seqinermullu tunniunneqarput, panerlutillu ukiumut toqqorneqartarlutik.", source: "Piniarneq", theme: .ground, subtheme: .aKeptPlace),
        Passage(text: "Qassiarsuk Kujataani nunaqarfiuvoq. Nunami tassani ivikkat nunarsuup avannaani naasut annerpaanut ilaapput, ukiullu tusintit qaangiuppata suli naapput.", source: "Kalaallit Nunaat", theme: .ground, subtheme: .aKeptPlace),
        Passage(text: "Piniarfik illuaraq nunami ungasissumi nikorfasarpoq. Piniartoq taassuma iluani unnuisarpoq, illuaraq allanut ammalluni matuneqarsimanani.", source: "Piniarneq", theme: .ground, subtheme: .aKeptPlace),
        Passage(text: "Nerisassat toqqorneqartarput nunap qerisortaani. Illup ataani nuna ukiuni tamani qerisuuvoq, neqerlu taamaalilluni qaammatini arlalinni pitsaassuseqarluartuarluni.", source: "Nerisassat", theme: .ground, subtheme: .aKeptPlace),
        Passage(text: "Kalaallisut -koorfik: iginneqarfik. Oqaasertaq atugassaaruttunut inissamik taaguuteqarpoq, nunaqarfiillu taamaattumik inissaqartitsisarlutik.", source: "Kalaallisut", theme: .ground, subtheme: .aKeptPlace),
        Passage(text: "Qimmit Kalaallit Nunaanni avannaani illersorneqarput. Qimmit allamit tikittut avannaamut ingerlanneqarsinnaanngillat, taamaalillutik qimmit kalaallit ataatsimoorlutik uninngasut.", source: "Piniarneq", theme: .ground, subtheme: .aKeptPlace),
        Passage(text: "Ilulissat kangerluat nunarsuarmi illersorneqartunut ilaavoq. Sermeq tassaniittoq ulluinnarni meterinik 20-nik ingerlasarpoq, nunarsuarmilu sukkanerpaanut ilaalluni.", source: "Kalaallit Nunaat", theme: .ground, subtheme: .aKeptPlace),
        Passage(text: "Kalaallisut illu illutoqarlu assigiinngillat. -toqaq utoqqaanermik oqaaseqarpoq, illutoqarlu illutut ittoq inuit ilaqutaannit ukiuni amerlasuuni atorneqarsimasoq.", source: "Kalaallisut", theme: .ground, subtheme: .aKeptPlace),
        Passage(text: "Nunami eqqissisimatitami tuttut, nannut umimmallu inuunerminnik ingerlatsipput. Nuna taanna 972.000 kvadratkilometerinik angissuseqarpoq, inuillu tassani najugaqanngillat.", source: "Kalaallit Nunaat", theme: .ground, subtheme: .aKeptPlace),

        // MARK: - Travel
        Passage(text: "Qisuit Kalaallit Nunaata sinaanut sikukkut tikittarput. Orpiit Sibiriamiit kuukkut immamut aallartinneqarput, sikullu qisuit nunami orpeqanngitsumut tunniussisarlugit.", source: "Nuna", theme: .travel, subtheme: .howASeedGoes),
        Passage(text: "Timmissat naatsiaqqanik nerisarput, kingornalu ungasissumi anartarlutik. Naatsiaq ataaseq taamaalilluni kilometerinik untritilinnik angalasinnaavoq, namminerisaminik aalannginnami.", source: "Timmissat", theme: .travel, subtheme: .howASeedGoes),
        Passage(text: "Naatsiaqqat ilaat anorimut naleqqussarneqarsimapput. Nutsartaqarput, anorersuarmilu qummut kaajallallutik nunami allami nallertarlutik.", source: "Naasut", theme: .travel, subtheme: .howASeedGoes),
        Passage(text: "Immami naatsiaqqat ilaat imermik puttasarput. Ukiuni marlunni immami uninngasinnaapput naasunngorsinnaassuseq annaanagu, kingornalu sinaanut tikillutik.", source: "Naasut", theme: .travel, subtheme: .howASeedGoes),
        Passage(text: "Sikup qaavani naatsiaqqat ukiukkut angalasarput. Sikoq aserorpat naatsiaqqat immamut nakkarput, imaqqullu taakkua sinaanut ungasissumut tikitsitsisarlutik.", source: "Siku", theme: .travel, subtheme: .howASeedGoes),
        Passage(text: "Naasut ilaat naatsiaqqaminnik nunamut nallatsitsisarput, allalli anorimut tunniussisarlutik. Naasoq ataaseq ilaannikkut marloriaammik siaruarterisarpoq.", source: "Naasut", theme: .travel, subtheme: .howASeedGoes),
        Passage(text: "Timmissat aggersut naatsiaqqanik amerlanertigut nassartaqartarput. Kalaallit Nunaanni naasut ilaat taamaalilluni nunarsuup aappaaninngaanniit tikisimapput.", source: "Timmissat", theme: .travel, subtheme: .howASeedGoes),
        Passage(text: "Kalaallisut -liarpoq: nunamut aallarpoq. Nuuliarpoq isumaqarpoq Nuummut aallartoq, oqaatsimi ataatsimi aallarnerup inissaatalu ataatsimoorlutik.", source: "Kalaallisut", theme: .travel, subtheme: .howASeedGoes),
        Passage(text: "Naatsiaq mikinerpaaq anorimut sisamaraterutaanik oqimaassuseqarpoq. Anorersuup nalaani kilometerit arlallit angalasinnaavoq, aatsaallu nunamut nallerluni.", source: "Naasut", theme: .travel, subtheme: .howASeedGoes),
        Passage(text: "Puisit imaani ungasissumut angalasarput, kingornalu inunngorfimminnut utertarlutik. Puisip aqqutissani qanoq nassaarinersua suli ilisimaneqanngilaq.", source: "Uumasut", theme: .travel, subtheme: .howASeedGoes),
        Passage(text: "Naatsiaqqat aputip ataani ukioq naallugu uninngasarput. Upernaakkut aput aatserpat imeq naatsiaqqanut aggortarpoq, taakkualu ataatsikkut naalersarlutik.", source: "Naasut", theme: .travel, subtheme: .howASeedGoes),
        Passage(text: "Uumasut mikisut ilulissat qaavani angalasarput. Iluliaq ataaseq nunarsuup avannaaninngaanniit kujammut ingerlasarpoq, uumasullu qaavaniittut ilaannaraat.", source: "Imaq", theme: .travel, subtheme: .howASeedGoes),
        Passage(text: "Kalaallit Nunaanni illoqarfiit aqqusinernik ataqatigiinneqanngillat. Angalaneq umiatsiakkut timmisartukkullu pisarpoq, ukiukkullu sikukkut qimussikkut.", source: "Kalaallit Nunaat", theme: .travel, subtheme: .theRoad),
        Passage(text: "Sikoq ukiukkut aqqutaanngortarpoq. Immap qaava aqqutissatut atorneqartarpoq nunanut allanut, aasakkullu aqqutissaq taanna peertarluni.", source: "Siku", theme: .travel, subtheme: .theRoad),
        Passage(text: "Kalaallisut -kkut: aqqutigalugu. Kaasi taanna aqqutissamik oqaluttuarpoq, aammalu piffissamik uteqqittartumik, soorlu ullaakkut.", source: "Kalaallisut", theme: .travel, subtheme: .theRoad),
        Passage(text: "Qamutit oqaatsit amerlasuunik naggasersuutillit: qamutit taamaallaat amerlasuunngorlutik oqaatsigineqarsinnaapput. Sannerutaat marluk avinneqarsinnaanngillat.", source: "Kalaallisut", theme: .travel, subtheme: .theRoad),
        Passage(text: "Qimussik qimmimik ataatsimik aqutsisoqarnani ingerlasarpoq. Qimmit siulliit aqqutissamik nassaarisarput, aqutsisorlu nipiminik kisiat aqutsilluni.", source: "Piniarneq", theme: .travel, subtheme: .theRoad),
        Passage(text: "Qajaq inuup ataatsip angallataa. Umiaq annerusoq ilaqutariit annertunerusut angallataraat, angallatit marluk atugassiaqarlutik assigiinngitsunik.", source: "Piniarneq", theme: .travel, subtheme: .theRoad),
        Passage(text: "Kalaallisut qajartorpoq: qajamik angalavoq. Oqaasertaq nerinermut atorneqartartoq atortumut atorneqarpat atornermik angalanermillu oqaaseqalersarpoq.", source: "Kalaallisut", theme: .travel, subtheme: .theRoad),
        Passage(text: "Kalaallisut ornigaq: ornikkat. Oqaaseq ornik- aggernermik oqaaseqartumit sananeqarpoq, tassa aqqutissap isua, oqaatsimi ataatsimi.", source: "Kalaallisut", theme: .travel, subtheme: .theRoad),
        Passage(text: "Sikup manngertussusia angalanissamut uuttortarneqartarpoq. Sikoq 10 centimeterinik issussuseqartoq inummut naammappoq, qimussinnullu 20-nik pisariaqartitsisoq.", source: "Siku", theme: .travel, subtheme: .theRoad),
        Passage(text: "Kalaallisut -mukarpoq: sumut aallarpoq. Illumukarpoq isumaqarpoq illup tungaanut aallartoq, aallarnerlu inissamut naggasersuutimit paasineqarluni.", source: "Kalaallisut", theme: .travel, subtheme: .theRoad),
        Passage(text: "Kangerluit ukiukkut aqqutaasarput. Kangerluup sikua sineriammit sineriammut ingerlanermut atorneqartarpoq, qaqqallu qaangernagit.", source: "Kalaallit Nunaat", theme: .travel, subtheme: .theRoad),
        Passage(text: "Timmisartoq Kalaallit Nunaanni sikoqanngitsumut mittarfimmut mittarpoq. Nunaqarfiit ilaat qulimiguulinnut kisimik tikinneqarsinnaapput, silarlu aalajangiisuulluni.", source: "Kalaallit Nunaat", theme: .travel, subtheme: .theRoad),
        Passage(text: "Kalaallisut qajaq nunarsuarmi oqaatsinut allanut ingerlasimavoq. Oqaaseq nunarsuup ilaani tamani ilisarineqarpoq, angallatillu kalaallit taassumannga taaguuteqarlutik.", source: "Oqaatsit", theme: .travel, subtheme: .farOff),
        Passage(text: "Kalaallisut annoraaq atisamik anorimut illersuutaasumik oqaaseqarpoq. Oqaaseq nunarsuup oqaasiinut allanut ingerlasimavoq, atisarlu taamaalilluni Kalaallit Nunaanniit aallarsimalluni.", source: "Oqaatsit", theme: .travel, subtheme: .farOff),
        Passage(text: "Inughuit Kalaallit Nunaata avannaani najugaqarput, nunarsuarmilu inuit avannarpasinnerpaat. Oqaasii kalaallisunit assigiinngitsuupput, oqaatsillu taakkua Inuktun taaguutigineqarlutik.", source: "Kalaallit Nunaat", theme: .travel, subtheme: .farOff),
        Passage(text: "Knud Rasmussen 1921-miit 1924-mut Kalaallit Nunaanniit Alaskamut qimussikkut ingerlavoq. Angalaneq taanna kilometerinik 18.000-nik takissuseqarpoq.", source: "Knud Rasmussen (1879-1933)", theme: .travel, subtheme: .farOff),
        Passage(text: "Inuit nunarsuup avannaani kilometerinik 5.000-nik ingerlasimapput Alaskamiit Kalaallit Nunaannut. Oqaasii suli assigiipput, nunallu akornanni ungasissuseq annertugaluartoq.", source: "Kalaallit Nunaat", theme: .travel, subtheme: .farOff),
        Passage(text: "Kalaallisut tikkuaatit ilaat takussaanngitsumut piffissamillu ungasissumut atorneqarput. Oqaaseq ataaseq ungasissusermik piffissamillu ataatsikkut oqaluttuarpoq.", source: "Kalaallisut", theme: .travel, subtheme: .farOff),
        Passage(text: "Kalaallisut oqaatsit pingasut atorneqarput: kalaallisut, tunumiisut inuktunlu. Oqaatsit taakkua ataatsimut atagaluarlutik, oqaluttullu ilaanni imminnut paasinngitsuulluni.", source: "Oqaatsit", theme: .travel, subtheme: .farOff),
        Passage(text: "Tunumi tikkuaatit sammiviisa kitaani atorneqartunit allaapput. Imaq tunumi kangimut inissisimammat oqaatsit qiterutaat allanngortarput, nunarlu oqaatsinik aalajangiisuulluni.", source: "Kalaallisut", theme: .travel, subtheme: .farOff),
        Passage(text: "Kalaallit Nunaat kujataaninngaanniit avannaanut kilometerinik 2.600-nik takissuseqarpoq. Kujataani orpiit naapput, avannaanilu ukioq naallugu sikoqarluni.", source: "Kalaallit Nunaat", theme: .travel, subtheme: .farOff),
        Passage(text: "Kalaallisut -luunniit: imaluunniit. Sumiuugaluaruttaluunniit isumaqarpoq sumiuugaluarutta pinngitsoorluta, tassa nunatta apeqqutaanngineranik.", source: "Kalaallisut", theme: .travel, subtheme: .farOff),
        Passage(text: "Kalaallit Nunaanni nunaqarfiit ilaat ukiumi ataatsimi ataasiarlutik umiarsuarmit tikinneqartarput. Sinerissaq sikoqarpat nunaqarfik qaammatini arlalinni imminut naammassisarpoq.", source: "Kalaallit Nunaat", theme: .travel, subtheme: .farOff),
        Passage(text: "Qilalugaq qernertaq Kalaallit Nunaata avannaani sikup ataani ukiisarpoq. Uumasoq taanna nunarsuarmi allami takuneqarneq ajorpoq, sikorlu illersuutigilluinnarlugu.", source: "Imaq", theme: .travel, subtheme: .farOff),

        // MARK: - Meeting
        Passage(text: "Kalaallisut naapippoq: aappaminik naapitsivoq. Oqaaseq marlunnik pisoqartitsivoq, ataasiinnaq naapitsisinnaanngilaq.", source: "Kalaallisut", theme: .meeting, subtheme: .theMoment),
        Passage(text: "Kalaallisut ataatsimiinneq: ataatsimut inissisimaneq. Oqaaseq ataaseq isumaqatigiinnermik pinnagu inissamik ataatsimik oqaluttuarpoq.", source: "Kalaallisut", theme: .meeting, subtheme: .theMoment),
        Passage(text: "Tikilluarit: tikinnerit pitsaassaaq. Kalaallisut inuk tikittoq oqaatsimi ataatsimi ilassineqartarpoq, oqaatsit taakkua pitsaassusermik nassuiaataallutik.", source: "Kalaallisut", theme: .meeting, subtheme: .theMoment),
        Passage(text: "Sikoq marluk imminnut nallerpat nipeqartarput. Imaani nipi taanna kilometerinik arlalinnik ungasissumit tusarneqarsinnaavoq, sikullu marluk ataatsimoorlutik.", source: "Siku", theme: .meeting, subtheme: .theMoment),
        Passage(text: "Kalaallisut -qatigiipput: ataatsimoorlutik suliapput. Oqaasertaq taanna amerlanertut kisimi atorneqarsinnaavoq, ataasiinnarmut naammannginnami.", source: "Kalaallisut", theme: .meeting, subtheme: .theMoment),
        Passage(text: "Kuuk marluk ataatsimoorpata atia allanngortarpoq. Kuup nutaap atia siulliit marluk ateqarunnaartitsivai, imerlu ataatsimoorluni ingerlaartuarluni.", source: "Nuna", theme: .meeting, subtheme: .theMoment),
        Passage(text: "Naasut ilaat imminut naapitsinnaveersaartarput. Naasoq ataaseq aappaminik pisariaqartitsivoq, naatsiaqqallu aatsaat marluk naapippata pinngortarlutik.", source: "Naasut", theme: .meeting, subtheme: .theMoment),
        Passage(text: "Aluu: ilassuut. Oqaaseq allamit tigusaavoq, ullumikkulli kalaallit ilassuutigisartagaannut ilaalluni.", source: "Kalaallisut", theme: .meeting, subtheme: .theMoment),
        Passage(text: "Imaq kissartoq immamut nillertumut naapippoq Kalaallit Nunaata sinaani. Naapinnerani nerisassat amerliartortarput, imarmiullu taakkani katersuuttarlutik.", source: "Imaq", theme: .meeting, subtheme: .theMoment),
        Passage(text: "Kalaallisut oqaatsit naapinnerini nipit allanngortarput. Oqaasertaq ataaseq aappaanut naleqqussartarpoq, marluullutillu oqaasertaanngorlutik.", source: "Oqaatsit", theme: .meeting, subtheme: .theMoment),
        Passage(text: "Qimmit qamutinut aallartinneqarpata siullermik imminnut misissortarput. Qimmit taamaalilluni tulleriissaarnerminnik aalajangiisarput, aqutsisorlu apeqqutaanani.", source: "Piniarneq", theme: .meeting, subtheme: .theMoment),
        Passage(text: "Kalaallisut -qqammer-: maanna kingorna pisoq. Oqaasertaq piffissamik sivikitsumik oqaluttuarpoq, tikeqqammerpoq oqarnermilu inuk aatsaat tikinnera nassuiarneqarluni.", source: "Kalaallisut", theme: .meeting, subtheme: .theMoment),
        Passage(text: "Kalaallisut aappaq: marluusut aappaat. Oqaaseq inuup aappaanik, atortup aappaanik pisunillu marlunnik ataatsikkut oqaluttuarpoq.", source: "Kalaallisut", theme: .meeting, subtheme: .twoThatNeedEachOther),
        Passage(text: "Qamutit sannerutaannik marlunnik peqarput. Aappaa ataasiinnaq sikup qaavani sanngiissuseqarpoq, marluullutilli oqimaatsunik ingerlatsisinnaallutik.", source: "Piniarneq", theme: .meeting, subtheme: .twoThatNeedEachOther),
        Passage(text: "Kalaallisut -giit: imminnut taamaattut. Ilaqutariit imminnut ilaqutaapput, qatanngutigiillu imminnut qatanngutaallutik. Oqaasertaq ataasiinnarmut atorneqarsinnaanngilaq.", source: "Kalaallisut", theme: .meeting, subtheme: .twoThatNeedEachOther),
        Passage(text: "Naasut Kalaallit Nunaanni timmissanit uumasunillu mikisunit ikiorneqartarput. Naasoq nammineq aalasinnaanngilaq, taamaattumillu allanut pisariaqartitsilluni.", source: "Naasut", theme: .meeting, subtheme: .twoThatNeedEachOther),
        Passage(text: "Kalaallisut naggasersuutit ilaat marlunnik inunnik oqaluttuarput: kina suliaqarnersoq kinalu suliaasoq. Naggaseq ataaseq oqaluttuaq tamarmi tigumiaavaa.", source: "Oqaatsit", theme: .meeting, subtheme: .twoThatNeedEachOther),
        Passage(text: "Kalaallisut -qatigaa: aappamminik suliaqarpoq. Oqaasertaq taanna inuup ataatsip suliaanik oqaluttuarsinnaanngilaq, marluk pisariaqartitsivoq.", source: "Kalaallisut", theme: .meeting, subtheme: .twoThatNeedEachOther),
        Passage(text: "Maniit naasunut siulliupput nunami ujaqqalimmi. Maniit ujaqqat aserorterpaat, naasullu allat aatsaat kingorna tassani naasinnaalersarlutik.", source: "Naasut", theme: .meeting, subtheme: .twoThatNeedEachOther),
        Passage(text: "Qajaq inuup ataatsip angallataavoq, umiarli ilaqutariit. Angallatit marluk pisariaqartitsipput, ataasiinnaq nunaqarfimmut naammannginnami.", source: "Piniarneq", theme: .meeting, subtheme: .twoThatNeedEachOther),
        Passage(text: "Sikoq immarlu imminnut atapput. Sikoq immap qaavata qerinerinit pinngortarpoq, aserorpallu immamut utertarluni, ataatsimoortumillu allanngortuartarlutik.", source: "Siku", theme: .meeting, subtheme: .twoThatNeedEachOther),
        Passage(text: "Kalaallisut -qat: peqataasoq. Suleqat suliffimmi peqataasuuvoq, ilinniaqatillu ilinniarfimmi. Oqaaseq ataaseq inuk aappaanik nassuiaataavoq.", source: "Kalaallisut", theme: .meeting, subtheme: .twoThatNeedEachOther),
        Passage(text: "Puisip amia inuup atisaanut pisariaqarpoq, inullu puisimut piniartuuvoq. Kalaallit oqaluttuaanni pissuseq taanna nerisassanik agguaassinermik malittarisassaqartinneqarpoq.", source: "Piniarneq", theme: .meeting, subtheme: .twoThatNeedEachOther),
        Passage(text: "Aqisseq ukiukkut qaqortuuvoq, aputillu qaqortuulluni. Timmiaq apummik illersorneqarpoq, aputillu timmiap nerisaanik illersuisarluni.", source: "Timmissat", theme: .meeting, subtheme: .twoThatNeedEachOther),
        Passage(text: "Kaffemik: kaffimik. Kalaallit nalliuttorsiornermi illuminnut ammasumik pulaartitsisarput, pulaartullu ulloq naallugu aggerlutik aallarlutillu.", source: "Kalaallit Nunaat", theme: .meeting, subtheme: .theMannersOfIt),
        Passage(text: "Qujanaq: qujaneqartariaqartoq. Oqaaseq quja- qujanermik oqaaseqartumit -naq-milu sananeqarpoq, tassa pisoq qujanartoq.", source: "Kalaallisut", theme: .meeting, subtheme: .theMannersOfIt),
        Passage(text: "Kalaallisut -laarit: qinnuteqaat qaneqqissartoq. Oqaasertaq taanna peqquineq saammartitsisarpaa, kalaallisullu qinnuteqaatit taamaalilluni oqaatsimi ataatsimi ilusilerneqartarlutik.", source: "Kalaallisut", theme: .meeting, subtheme: .theMannersOfIt),
        Passage(text: "Kalaallisut -niarit: peqquineq qanilaartoq. Peqquineq oqaasertamik ilaqanngitsoq sakkortuulluinnarpoq, taamaattumik oqaasertat qaneqqissaataasut atorneqartuarput.", source: "Kalaallisut", theme: .meeting, subtheme: .theMannersOfIt),
        Passage(text: "Inuulluarit: inuunerit pitsaassaaq. Oqaaseq aallartitsinermi atorneqartarpoq, aammalu kalaallit inuulluaqqusaataattut.", source: "Kalaallisut", theme: .meeting, subtheme: .theMannersOfIt),
        Passage(text: "Kalaallisut -gooq: oqartoqarpoq. Oqaasertaq taanna oqaluttuarnermi atorneqartarpoq, aammalu inuit inuulluaqqullugit: Makkagooq inuulluarili.", source: "Kalaallisut", theme: .meeting, subtheme: .theMannersOfIt),
        Passage(text: "Piniartup pisaa nunaqarfimmi agguarneqartarpoq. Puisi pisaq ilaqutariinnut assigiimmik agguarneqarpoq, pisassarlu piniartup kisimi pigisaanngitsoq.", source: "Piniarneq", theme: .meeting, subtheme: .theMannersOfIt),
        Passage(text: "Takuss: takussaagut. Oqaaseq naanngitsoq aallarnermi atorneqartarpoq, isumaalu naapinnissamut siunnerfeqarluni.", source: "Kalaallisut", theme: .meeting, subtheme: .theMannersOfIt),
        Passage(text: "Kalaallisut naalanniarit: naalatsigit. Oqaaseq meeqqanut oqaatigineqartarpoq, ilanngullugulu -tar- ilanngunneqarpat eqqaasitsissutaanngorluni.", source: "Kalaallisut", theme: .meeting, subtheme: .theMannersOfIt),
        Passage(text: "Kalaallisut -aa: oqaluuseq. Inuk inungaanngortinneqarpat inuk aggersarneqarpoq, oqaasertarlu taanna ataqqinninnermik takutitsisarluni.", source: "Kalaallisut", theme: .meeting, subtheme: .theMannersOfIt),
        Passage(text: "Kaffemikkut inuit ilassinneqartarput ateqqaarneqarnatik. Pulaartut kaffisorlutik nerisarput, kingornalu aallarlutik allanut inissaqartitsillutik.", source: "Kalaallit Nunaat", theme: .meeting, subtheme: .theMannersOfIt),
        Passage(text: "Kalaallisut -qatiseraa: aappani suliaqateqqusarpaa. Oqaasertaq taanna qinnuteqaatitut atorneqartarpoq, marlunnillu inunnik pisoqartitsivoq.", source: "Kalaallisut", theme: .meeting, subtheme: .theMannersOfIt),

        // MARK: - Kinship
        Passage(text: "Kalaallisut ilaqutariit: imminnut ilaqutaasut. Oqaaseq ataasiakkaanik oqaluttuanngilaq, imminnullu attaveqaatinik, taamaattumillu ataasiinnarmut atorneqarsinnaanani.", source: "Kalaallisut", theme: .kinship, subtheme: .grownTogether),
        Passage(text: "Kalaallisut inuiaqatigiit: inuit imminnut peqataasut. Oqaaseq inunnik amerlasuunik ataatsimut katitigaasunik oqaluttuarpoq, inuiaqatigiinnerlu attaveqaatinit pinngortinneqarluni.", source: "Kalaallisut", theme: .kinship, subtheme: .grownTogether),
        Passage(text: "Kalaallit ateqartitsinerannik ileqqoqarput. Meeraq toqusumik ateqartinneqarpat ilaqutariinni inissaa taassuma inissaanut naleqqiullugu paasineqartarpoq.", source: "Kalaallit Nunaat", theme: .kinship, subtheme: .grownTogether),
        Passage(text: "Kalaallisut ateqatigiit: ateq ataaseq marlunnut. Inuit marluk ateqatigiippata attaveqaateqalersarput, ilaqutaanngikkaluarlutik.", source: "Kalaallisut", theme: .kinship, subtheme: .grownTogether),
        Passage(text: "Qimmit qamutini tulleriissaarnermik pilersitsisarput. Qimmeq ataaseq siulliusarpoq, sinnerilu taassuma malinnaarnera malillugu ingerlasarlutik.", source: "Piniarneq", theme: .kinship, subtheme: .grownTogether),
        Passage(text: "Kalaallisut -qatigiit: suna ataaseq peqatigalugu. Suleqatigiit ataatsimik suliaqarput, ilinniaqatigiillu ataatsimik ilinniagaqarlutik.", source: "Kalaallisut", theme: .kinship, subtheme: .grownTogether),
        Passage(text: "Maniit naasullu ataatsimoortumik uumapput. Naasup manii nerisassiorput, maniillu naasumit imermik illersorneqarlutik, marluullutillu ataatsimik uumasunngorlutik.", source: "Naasut", theme: .kinship, subtheme: .grownTogether),
        Passage(text: "Kalaallisut -giiaat: amerlanertut imminnut taamaattut. Oqaasertaq ataasiakkaanut atorneqarsinnaanngilaq, amerlanertuinnarmut naleqqutilluni.", source: "Kalaallisut", theme: .kinship, subtheme: .grownTogether),
        Passage(text: "Nunaqarfimmi inuit amerlanertigut ilaqutaapput. Inuk ataaseq nunaqarfimmi tamanit ilisarineqarpoq, ateralu ilaquttaminut ilanngunneqartarluni.", source: "Kalaallit Nunaat", theme: .kinship, subtheme: .grownTogether),
        Passage(text: "Ilulissat marluk immami ataatsimoortarput. Sikoq akornanni pinngorpoq, ilulissallu marluk ingerlaannaq ataatsimoorlutik ingerlaartarlutik.", source: "Siku", theme: .kinship, subtheme: .grownTogether),
        Passage(text: "Kalaallisut asasaq: asaneqartoq. Oqaaseq asa- asanninnermik oqaaseqartumit sananeqarpoq, isumaalu tassaalluni inuk allamit asaneqartoq.", source: "Kalaallisut", theme: .kinship, subtheme: .grownTogether),
        Passage(text: "Naasut nunami issittumi kikiakkatimikkut ataqatigiipput. Naasut ataasiakkaat takussaapput, ataanili naasut tamarmik ataatsimoorlutik uumasunngorsimallutik.", source: "Naasut", theme: .kinship, subtheme: .grownTogether),
        Passage(text: "Kalaallisut qatanngutit ateqartinneqarnerat oqartup angutaanera arnaanerlu apeqqutaavoq. Aammalu kikkut siulliusimanerat, taamaalilluni ateq marlunnik nalunaarsuuteqarluni.", source: "Kalaallisut", theme: .kinship, subtheme: .theWordsForIt),
        Passage(text: "Kalaallisut -kkut: taassuma ilaqutai. Kaalikkut isumaqarpoq Kaali ilaquttailu. Oqaatsimi ataatsimi inuk ilaquttanilu katinneqarput.", source: "Kalaallisut", theme: .kinship, subtheme: .theWordsForIt),
        Passage(text: "Kalaallisut inuk sisamaat: oqaluttuami inuup nammineq pigisaa allallu pigisaat immikkut nalunaarsorneqarput. Illuni namminermik illumik oqaaseqarpoq, illualu allap illuanik.", source: "Kalaallisut", theme: .kinship, subtheme: .theWordsForIt),
        Passage(text: "Kalaallisut -lu: aamma. Kaali Piitarlu isumaqarpoq Kaali Piitarlu, oqaasertarlu aappaanut ilanngunneqartoq, siullermut pinnagu.", source: "Kalaallisut", theme: .kinship, subtheme: .theWordsForIt),
        Passage(text: "Kalaallisut asavakkit: asavakkit. Oqaaseq ataaseq asasumik asaneqartumillu ataatsikkut oqaluttuarpoq, naggasersuutaani marluullutik.", source: "Kalaallisut", theme: .kinship, subtheme: .theWordsForIt),
        Passage(text: "Kalaallisut angaju nukarlu: angaju siulliuvoq, nukaq kingulliulluni. Ateq ataaseq inunngornerup tulleriissaarnerinik nalunaarsuutaavoq.", source: "Kalaallisut", theme: .kinship, subtheme: .theWordsForIt),
        Passage(text: "Kalaallisut ikinngut: ikinngutigisaq. Oqaaseq inuup ilaqutaanngitsumik attaveqaataanik oqaluttuarpoq, attaveqaatillu taanna ilaquttatut nalilerneqartarluni.", source: "Kalaallisut", theme: .kinship, subtheme: .theWordsForIt),
        Passage(text: "Kalaallisut meeraq meeqqallu: oqaaseq ataaseq inuup ukiuinik siullernik oqaluttuarpoq. Meeqqannguaq oqarneq asanninnermik takutitsivoq, mikissusermik pinnagu.", source: "Kalaallisut", theme: .kinship, subtheme: .theWordsForIt),
        Passage(text: "Kalaallisut ilaquttat oqaatsit amerlasuut atorneqarput. Anaana, ataata, aanaa aataarlu ataatsimut atapput, ateqartitsinerallu ilaqutariinni inissaminnik takutitsisarluni.", source: "Kalaallisut", theme: .kinship, subtheme: .theWordsForIt),
        Passage(text: "Kalaallisut oqaatsit isumaannik naggasersuutinik pilersitsisut arlaqarput. Ilaqutaqarpoq isumaqarpoq ilaquttaqartoq, oqaatsimi ataatsimi peqarnerlu inuillu katinneqarlutik.", source: "Oqaatsit", theme: .kinship, subtheme: .theWordsForIt),
        Passage(text: "Kalaallisut nalunngilara: naluneq naggasersorneqarpoq. Ilisimaneq oqaatsimi ilisimannginnerup naapertuutinnginneratut oqaatigineqartarpoq.", source: "Kalaallisut", theme: .kinship, subtheme: .theWordsForIt),
        Passage(text: "Kalaallisut suleqat oqaatsinit marlunnit sananeqarpoq: suli- suliamik oqaaseqartoq, -qat-lu peqataasumik. Isumaa tassaavoq inuk aappanut suleqataasoq.", source: "Kalaallisut", theme: .kinship, subtheme: .theWordsForIt),
        Passage(text: "Kalaallisut Kaali Piitarlu: oqaatsit marluk oqaasertamik ataatsimik ataqatigiissinneqarput. Aamma-p inissaa aappaani inissisimavoq, siullermi pinnagu.", source: "Kalaallisut", theme: .kinship, subtheme: .twoPeople),
        Passage(text: "Kalaallisut Nuka Piitamit anneruvoq: naleqqiussineq -mit-mik naggasersorneqarpoq. Inuk aappaminngaanniit annerusarpoq, aappaanut pinnagu.", source: "Kalaallisut", theme: .kinship, subtheme: .twoPeople),
        Passage(text: "Kalaallisut Piitaq Nukatut angitigaaq: assigiinneq -tut-mik naggasersorneqarpoq. Naggaseq taanna oqaatsinut aamma atorneqartarpoq, kalaallisut oqaatsit atiannut.", source: "Kalaallisut", theme: .kinship, subtheme: .twoPeople),
        Passage(text: "Kalaallisut ataatsimoorneq: ataatsimut ittuuneq. Oqaaseq ataaseq inunnik amerlasuunik ataatsimut katitigaasunik oqaluttuarpoq, ataasiakkaanik pinnagit.", source: "Kalaallisut", theme: .kinship, subtheme: .twoPeople),
        Passage(text: "Kalaallisut takuvaa oqarnermi kina takusoq kinalu takusaq naggasersuutimi ataatsimi nalunaarsorneqarput. Oqaaseq marlunnik inunnik tigumiaavoq, oqaatsit marluk pinnagit.", source: "Oqaatsit", theme: .kinship, subtheme: .twoPeople),
        Passage(text: "Kalaallisut -qatigaa: aappaminik peqateqarluni suliaqarpoq. Oqaasertaq taanna inuup ataatsip suliaanik oqaluttuarsinnaanngilaq.", source: "Kalaallisut", theme: .kinship, subtheme: .twoPeople),
        Passage(text: "Umiaq inunnik amerlanerusunik pisariaqartitsivoq. Ipuutit ataatsimoortumik atorneqartarput, umiarlu taamaalilluni ataasiakkaanit ingerlanneqarsinnaanani.", source: "Piniarneq", theme: .kinship, subtheme: .twoPeople),
        Passage(text: "Kalaallisut -qatigiipput: imminnut suliaqarput. Oqaasertaq taanna amerlanertut naggasersuutinik pisariaqartitsivoq, marlunniit ikinnerusunut naammannginnami.", source: "Kalaallisut", theme: .kinship, subtheme: .twoPeople),
        Passage(text: "Puisit marluk allumi anersaartaartarput. Allu ataaseq marlunnit atorneqarpat sivisunerusumik ammasuuvoq, ataasiinnarmilli matoqqasarluni.", source: "Uumasut", theme: .kinship, subtheme: .twoPeople),
        Passage(text: "Kalaallisut oqarfigaa: allamut oqarpoq. Oqarpoq oqaaseqarnermik kisimik oqaluttuarpoq, oqarfigaali kimut oqartoqarnera ilanngullugu.", source: "Kalaallisut", theme: .kinship, subtheme: .twoPeople),
        Passage(text: "Timmissat ilaat inuunerminni ataasiinnarmik aappaqartarput. Aappariit ukiumut ataasiarlutik naapittarput, qeqertamilu ataatsimi piaqqiortarlutik.", source: "Timmissat", theme: .kinship, subtheme: .twoPeople),
        Passage(text: "Kalaallisut qutsavigaa: taassuminnga qujavoq. Qujavoq qujanermik kisimik oqaluttuarpoq, qutsavigaali kina qujaneqarnersoq ilanngullugu.", source: "Kalaallisut", theme: .kinship, subtheme: .twoPeople),

        // MARK: - Peace
        Passage(text: "Kalaallisut -paluk: suliap nipaa. Oqaasertaq taanna suliamik oqaaseqartumit taagutaasumik pilersitsisarpoq, tassa suliap tusarnaataa.", source: "Kalaallisut", theme: .peace, subtheme: .quietAsASound),
        Passage(text: "Kalaallisut -palaarpoq: arlaannik pisoqartoq tusarneqarsinnaavoq. Oqaasertaq kina suna pinersoq oqaatiginngilaa, tusaaneq kisiat nalunaarsorlugu.", source: "Kalaallisut", theme: .peace, subtheme: .quietAsASound),
        Passage(text: "Kalaallisut nipeqanngilaq: nipimik peqanngilaq. Nipi nipimik taagutaavoq, oqartullu nipaanik uumasullu nipaanik ataatsikkut oqaluttuarluni.", source: "Kalaallisut", theme: .peace, subtheme: .quietAsASound),
        Passage(text: "Aput nutaaq nipinik tigusisarpoq. Nittaalarnerata kingorna nunaqarfik nipaatsunngortarpoq, nipillu ungasissumut ingerlanngitsuunngorlutik.", source: "Sila", theme: .peace, subtheme: .quietAsASound),
        Passage(text: "Sikoq nipeqartarpoq. Sikup aserornerani nipi kilometerinik arlalinnik ungasissumut ingerlasinnaavoq, immallu ataani suli tusarneqarluni.", source: "Siku", theme: .peace, subtheme: .quietAsASound),
        Passage(text: "Kalaallisut -sunni: sumi tipaa. Oqaasertaq taanna tipimut atorneqarpoq, -paluk-lu nipimut, oqaasertat marluk ilusimikkut assigiillutik.", source: "Kalaallisut", theme: .peace, subtheme: .quietAsASound),
        Passage(text: "Sermersuup ataani imeq ingerlaartuarpoq. Nipaa qulaaninngaanniit tusarneqanngilaq, sermerup iluanili nipi ataavartuartoq.", source: "Siku", theme: .peace, subtheme: .quietAsASound),
        Passage(text: "Ukiukkut nipi sikup qaavatigut ungasissumut ingerlasinnaavoq. Silap kiassusia qulaani annerulerpat nipi ammut utertinneqartarpoq, oqaluttullu kilometerinit ungasinnerusumit tusarneqarlutik.", source: "Sila", theme: .peace, subtheme: .quietAsASound),
        Passage(text: "Qimmit unippata nipeqarunnaartarput. Qamutit nipaat aputip nipaalu ataatsikkut unittarput, aqutsisorlu taamaalilluni namminermik anersaartaarnini tusaalersarlugu.", source: "Piniarneq", theme: .peace, subtheme: .quietAsASound),
        Passage(text: "Arsarnerit nipeqartutut tusaaneqartarput, uuttortaanerilli suli aalajangersimasumik takutitsinngillat. Inuit ilaat nipimik annikitsumik tusaasimanerarput.", source: "Qilak", theme: .peace, subtheme: .quietAsASound),
        Passage(text: "Nunami eqqissisimatitami nipi inunnit pinngortitaq atuuppoq. Uumasut nipaat, anorip nipaa sermerullu nipaa kisimik tusarneqarput.", source: "Kalaallit Nunaat", theme: .peace, subtheme: .quietAsASound),
        Passage(text: "Timmissat qeqertani unnuakkut nipaatsunngortarput. Aasap qeqqani qaammarissuugaluartoq timmissat nipaannguutitsiartarput, ulloq unnuarlu avissaarutaanngikkaluartoq.", source: "Timmissat", theme: .peace, subtheme: .quietAsASound),
        Passage(text: "Immami ilulissat aalanerinit nipi pinngortarpoq. Nipi taanna imaani kilometerinik untritilinnik ingerlasinnaavoq, imarmiullu taassuminnga malinnaasinnaallutik.", source: "Imaq", theme: .peace, subtheme: .quietAsASound),
        Passage(text: "Kalaallisut eqqissineq: eqqissisimaneq. Oqaaseq inuup isumaata qanoq innerinik oqaluttuarpoq, aammalu nunap qanoq issusianik, oqaatsit marluk pinnagit.", source: "Kalaallisut", theme: .peace, subtheme: .theWordsForStopping),
        Passage(text: "Kalaallisut ajunngilaq: ajortuunngilaq. Pitsaassuseq oqaatsimi ajortuunngineq atorlugu nassuiarneqarpoq, oqaasertarlu taanna atugassaqartuarluni.", source: "Kalaallisut", theme: .peace, subtheme: .theWordsForStopping),
        Passage(text: "Kalaallisut naammappoq: naammalluni. Oqaaseq amerlanerusumik pisariaqartitsinnginnermik nassuiaataavoq, unitsitsinermillu pinnagu.", source: "Kalaallisut", theme: .peace, subtheme: .theWordsForStopping),
        Passage(text: "Kalaallit Tunumi oqaluttuartut akerleriittut erinarsuutigut isumaqatigiissarput. Isumaqatigiinngissut inunnut tusarnaartunut saqqummiunneqarpoq, aallaqqaataalu taamaalilluni naggasersorneqarluni.", source: "Kalaallit oqaluttuaat", theme: .peace, subtheme: .theWordsForStopping),
        Passage(text: "Kalaallisut -naveersaarpoq: pinaveersaartoq. Oqaasertaq taanna pinngitsoornermik pinnagu, pinaveersaarnermik nalunaarsuutaavoq.", source: "Kalaallisut", theme: .peace, subtheme: .theWordsForStopping),
        Passage(text: "Kalaallisut nerineq ajorpunga: qaqugukkulluunniit nerinnginnera. Oqaatsit marluk oqaasertatut ataatsitut atorneqarput, avinneqarsinnaanatillu.", source: "Kalaallisut", theme: .peace, subtheme: .theWordsForStopping),
        Passage(text: "Kalaallisut -tsaalivaa: pinaveersaartippaa. Oqaasertaq taanna inuup ataatsip allap suliaanik unitsitsineranik nalunaarsuutaavoq.", source: "Kalaallisut", theme: .peace, subtheme: .theWordsForStopping),
        Passage(text: "Kalaallisut -qqunngilaa: pinnaveersaarpaa. Peqquineq naggasersorneqarpat inerteqqutaanngorpoq, oqaatsillu ataatsimi peqquineq inerteqqutaalu naapillutik.", source: "Kalaallisut", theme: .peace, subtheme: .theWordsForStopping),
        Passage(text: "Kalaallisut unippoq: aalanera naavoq. Oqaaseq angallammut, uumasumut suliamullu atorneqarsinnaavoq, unittarfimmillu -vik-mik pilersitsisinnaalluni.", source: "Kalaallisut", theme: .peace, subtheme: .theWordsForStopping),
        Passage(text: "Sikoq aserorunnaarpat imaq nipaatsunngortarpoq. Ukiup ilaani taanna imarmiunut qasuersaarfiuvoq, malillu unittarnerini.", source: "Imaq", theme: .peace, subtheme: .theWordsForStopping),
        Passage(text: "Anorersuup naanerani nunaqarfik nipaatsunngortarpoq. Anori ulluni arlalinni nipeqarsimappat unitsinnera tusarneqarluinnartarpoq, nipaatsuunerlu nutaajusutut ippoq.", source: "Sila", theme: .peace, subtheme: .theWordsForStopping),
        Passage(text: "Kalaallisut -nngilerpoq: sivisuumik pisimanngitsoq. Oqaasertaq pisimanngitsuunermik piffissamillu ataatsikkut oqaluttuarpoq, unitsitsinermik pinnagu.", source: "Kalaallisut", theme: .peace, subtheme: .theWordsForStopping),
        Passage(text: "Nuna eqqissisimatitaq inunnit unitsinneqarsimasuuvoq. Piniarneq assartuinerlu tassani inerteqqutaapput, uumasullu taamaalilluni namminneq inuunerminnik ingerlatsisut.", source: "Kalaallit Nunaat", theme: .peace, subtheme: .theWordsForStopping),
        Passage(text: "Kalaallisut -luusaarpoq: eqqissisimallugu pisoq. Oqaasertaq taanna suliap sukkassusianik oqaluttuarpoq, naammassinerata piffissaanik pinnagu.", source: "Kalaallisut", theme: .peace, subtheme: .atEase),
        Passage(text: "Kalaallisut -rusaarpoq: arriitsumik pisoq. Oqaasertaq sukkanngitsuunermik nalunaarsuutaavoq, kisianni sianiitsuunermik pinnagu.", source: "Kalaallisut", theme: .peace, subtheme: .atEase),
        Passage(text: "Kalaallisut -simaarpoq: pisimanerata kingorna nuannaarpoq. Oqaasertaq taanna naammassisimanerup kingunerisaanik qanoq innermik nalunaarsuutaavoq.", source: "Kalaallisut", theme: .peace, subtheme: .atEase),
        Passage(text: "Qulleq illu qaammartippaa kiassarlugulu. Ikumatitaq unnuaq naallugu ikumasarpoq, illullu iluani kiassuseq inuit timaannit pilersinneqartuarluni.", source: "Kalaallit Nunaat", theme: .peace, subtheme: .atEase),
        Passage(text: "Kalaallisut siniffik: siniffiuvoq. Oqaaseq sinik- sininnermik oqaaseqartumit -vik-milu inissamik oqaaseqartumit sananeqarpoq.", source: "Kalaallisut", theme: .peace, subtheme: .atEase),
        Passage(text: "Kalaallisut -llatsiarpoq: sivikitsumik pisoq. Oqaasertaq taanna piffissap sivikitsup nalaani pisumik nalunaarsuutaavoq, unitsitsinermik pinnagu.", source: "Kalaallisut", theme: .peace, subtheme: .atEase),
        Passage(text: "Kalaallisut illumiitillunga: illumiitillunga. Oqaatsimi ataatsimi inissaq piffissarlu katinneqarput, oqaatsit sisamat pinnagit.", source: "Kalaallisut", theme: .peace, subtheme: .atEase),
        Passage(text: "Kalaallisut kaffisortarpunga: kaffisortuarpunga. Oqaasertaq -tar- pisartumik nalunaarsuutaavoq, kaffisorpunga oqarnerlu maannakkut pisumik.", source: "Kalaallisut", theme: .peace, subtheme: .atEase),
        Passage(text: "Nanoq aasakkut ujaqqat qaavanni nalasarpoq. Kiassuseq annertoq nannup timaanut annertuallaartarpoq, taamaattumillu ullup ilaanik anersaartaartuinnarluni.", source: "Uumasut", theme: .peace, subtheme: .atEase),
        Passage(text: "Kalaallisut -nnguarpoq: tuppallersaataasoq. Oqaasertaq mikissusermik pinnagu asanninnermik saammaassinermillu nalunaarsuutaavoq.", source: "Kalaallisut", theme: .peace, subtheme: .atEase),
        Passage(text: "Qimmit ingerlaneq naammassippat aputimi nalasarput. Aput timimikkut ammalussumik matoqqavaat, anersaartaarnerallu aputip ataani kissarsuutaalluni.", source: "Piniarneq", theme: .peace, subtheme: .atEase),
        Passage(text: "Puisi immami sinissinnaavoq. Anersaartaarnissamut makittarpoq, kingornalu ammut nakkarluni, sininnerlu taamaalilluni marloriaartumik agguarneqarluni.", source: "Uumasut", theme: .peace, subtheme: .atEase),
    ]
}
